Add-Type -AssemblyName System.Net.Sockets

$transcriptPath = "C:\Logs\PowerShell_Transcript_$(Get-Date -Format 'yyyyMMdd_HHmmss').txt"
$serverAddress = "192.168.1.100"
$serverPort = 1234
$intervalMinutes = 5

function Start-TranscriptLogging {
    Start-Transcript -Path $transcriptPath -Append
    Write-Output "Transcript started at $(Get-Date). Log file: $transcriptPath"
}

function Stop-TranscriptLogging {
    Stop-Transcript
    Write-Output "Transcript stopped at $(Get-Date)."
}

function Send-FileViaTCP {
    param (
        [string]$filePath,
        [string]$server,
        [int]$port
    )

    try {
        $tcpClient = New-Object System.Net.Sockets.TcpClient($server, $port)
        $stream = $tcpClient.GetStream()
        $fileBytes = [System.IO.File]::ReadAllBytes($filePath)
        $stream.Write($fileBytes, 0, $fileBytes.Length)
        $stream.Close()
        $tcpClient.Close()
        Write-Output "File sent successfully to $server:$port at $(Get-Date)."
    }
    catch {
        Write-Output "Error sending file: $_"
    }
}

Start-TranscriptLogging

while ($true) {
    Start-Sleep -Seconds ($intervalMinutes * 60)
    Stop-TranscriptLogging
    Send-FileViaTCP -filePath $transcriptPath -server $serverAddress -port $serverPort
    Start-TranscriptLogging
}
