```swift
import AVFoundation
import Cocoa
import Network

class ScreenRecorder {
    private var displayLink: CVDisplayLink?
    private var captureSession: AVCaptureSession?
    private var videoOutput: AVCaptureVideoDataOutput?
    private var udpConnection: NWConnection?
    private var isRunning = false

    func startRecording(to address: String, port: UInt16) {
        guard !isRunning else { return }
        isRunning = true

        let host = NWEndpoint.Host(address)
        let port = NWEndpoint.Port(rawValue: port)!
        udpConnection = NWConnection(host: host, port: port, using: .udp)

        udpConnection?.stateUpdateHandler = { state in
            switch state {
            case .ready:
                print("UDP connection ready")
            case .failed(let error):
                print("UDP connection failed: \(error)")
            default:
                break
            }
        }

        udpConnection?.start(queue: .global())

        let mainDisplayID = CGMainDisplayID()
        var displayLink: CVDisplayLink?
        CVDisplayLinkCreateWithCGDisplay(mainDisplayID, &displayLink)

        self.displayLink = displayLink
        CVDisplayLinkSetOutputHandler(displayLink!) { [weak self] _, _, _, _, _ in
            self?.captureScreen()
            return kCVReturnSuccess
        }

        CVDisplayLinkStart(displayLink!)
    }

    func stopRecording() {
        guard isRunning else { return }
        isRunning = false

        displayLink.map { CVDisplayLinkStop($0) }
        displayLink = nil

        udpConnection?.cancel()
        udpConnection = nil

        captureSession?.stopRunning()
        captureSession = nil
    }

    private func captureScreen() {
        let screenRect = CGDisplayBounds(CGMainDisplayID())
        let imageRef = CGDisplayCreateImage(screenRect)

        guard let imageRef = imageRef,
              let bitmapRep = NSBitmapImageRep(cgImage: imageRef),
              let imageData = bitmapRep.representation(using: .jpeg, properties: [:]) else {
            return
        }

        sendData(imageData)
    }

    private func sendData(_ data: Data) {
        udpConnection?.send(content: data, completion: .contentProcessed { error in
            if let error = error {
                print("Error sending data: \(error)")
            }
        })
    }
}

let recorder = ScreenRecorder()
recorder.startRecording(to: "127.0.0.1", port: 12345)

RunLoop.main.run()
