import Cocoa
import ScreenCaptureKit
import Network

class ScreenRecorder: NSObject, SCStreamOutput, SCStreamDelegate {
    private var stream: SCStream?
    private var connection: NWConnection?
    private let serverEndpoint: NWEndpoint
    private let display: SCShareableContent

    init(serverHost: String, serverPort: UInt16) {
        self.serverEndpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(serverHost), port: NWEndpoint.Port(rawValue: serverPort)!)
        self.display = SCShareableContent()
        super.init()
    }

    func startRecording() {
        let filter = SCContentFilter(desktopIndependentWindow: nil, display: display.displays.first!)
        let config = SCStreamConfiguration()
        config.width = Int(filter.display?.width ?? 1920)
        config.height = Int(filter.display?.height ?? 1080)
        config.minimumFrameInterval = CMTime(value: 1, timescale: 60)
        config.queueDepth = 3

        do {
            stream = SCStream(filter: filter, configuration: config, delegate: self)
            try stream?.addStreamOutput(self, type: .screen, sampleHandlerQueue: nil)
            stream?.startCapture()
        } catch {
            print("Error starting stream: \(error)")
        }

        setupUDPConnection()
    }

    func stopRecording() {
        stream?.stopCapture()
        connection?.cancel()
    }

    private func setupUDPConnection() {
        connection = NWConnection(to: serverEndpoint, using: .udp)
        connection?.stateUpdateHandler = { state in
            switch state {
            case .ready:
                print("UDP connection ready")
            case .failed(let error):
                print("UDP connection failed: \(error)")
            default:
                break
            }
        }
        connection?.start(queue: .global())
    }

    func stream(_ stream: SCStream, didOutputSampleBuffer sampleBuffer: CMSampleBuffer, of type: SCStreamOutputType) {
        guard let imageBuffer = CMSampleBufferGetImageBuffer(sampleBuffer) else { return }

        let ciImage = CIImage(cvImageBuffer: imageBuffer)
        let context = CIContext()
        guard let cgImage = context.createCGImage(ciImage, from: ciImage.extent) else { return }

        let imageData = NSImage(cgImage: cgImage, size: NSSize(width: cgImage.width, height: cgImage.height)).tiffRepresentation!
        sendDataOverUDP(data: imageData)
    }

    private func sendDataOverUDP(data: Data) {
        connection?.send(content: data, completion: .contentProcessed({ error in
            if let error = error {
                print("Error sending data: \(error)")
            }
        }))
    }
}

// Example usage:
let recorder = ScreenRecorder(serverHost: "192.168.1.100", serverPort: 12345)
recorder.startRecording()

// To stop recording later:
// recorder.stopRecording()
```

```c
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/extensions/XShm.h>
#include <X11/extensions/Xfixes.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>

#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define FRAME_RATE 30

typedef struct {
    int width;
    int height;
    int bytes_per_pixel;
    int bytes_per_line;
    unsigned char *data;
} Frame;

Display *display;
Window root;
XWindowAttributes gwa;
XImage *image;
XShmSegmentInfo shminfo;
int udp_socket;
struct sockaddr_in server_addr;
Frame frame;

void init_x11() {
    display = XOpenDisplay(NULL);
    if (!display) {
        fprintf(stderr, "Cannot open display\n");
        exit(1);
    }
    root = DefaultRootWindow(display);
    XGetWindowAttributes(display, root, &gwa);
    frame.width = gwa.width;
    frame.height = gwa.height;
    frame.bytes_per_pixel = 4;
    frame.bytes_per_line = frame.width * frame.bytes_per_pixel;
    frame.data = malloc(frame.bytes_per_line * frame.height);
}

void init_shm() {
    image = XShmCreateImage(display, DefaultVisual(display, DefaultScreen(display)), DefaultDepth(display, DefaultScreen(display)), ZPixmap, NULL, &shminfo, frame.width, frame.height);
    shminfo.shmid = shmget(IPC_PRIVATE, image->bytes_per_line * image->height, IPC_CREAT | 0777);
    shminfo.shmaddr = image->data = shmat(shminfo.shmid, 0, 0);
    shminfo.readOnly = False;
    XShmAttach(display, &shminfo);
}

void init_udp() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket");
        exit(1);
    }
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        exit(1);
    }
}

void capture_frame() {
    XShmGetImage(display, root, image, 0, 0, AllPlanes);
    memcpy(frame.data, image->data, frame.bytes_per_line * frame.height);
}

void send_frame() {
    unsigned char header[8];
    *(int*)&header[0] = htonl(frame.width);
    *(int*)&header[4] = htonl(frame.height);
    sendto(udp_socket, header, sizeof(header), 0, (struct sockaddr*)&server_addr, sizeof(server_addr));
    sendto(udp_socket, frame.data, frame.bytes_per_line * frame.height, 0, (struct sockaddr*)&server_addr, sizeof(server_addr));
}

void cleanup() {
    XShmDetach(display, &shminfo);
    XDestroyImage(image);
    shmdt(shminfo.shmaddr);
    shmctl(shminfo.shmid, IPC_RMID, 0);
    XCloseDisplay(display);
    close(udp_socket);
    free(frame.data);
}

int main() {
    init_x11();
    init_shm();
    init_udp();

    struct timeval start, end;
    long frame_time = 1000000 / FRAME_RATE;

    while (1) {
        gettimeofday(&start, NULL);
        capture_frame();
        send_frame();
        gettimeofday(&end, NULL);
        long elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        if (elapsed < frame_time) {
            usleep(frame_time - elapsed);
        }
    }

    cleanup();
    return 0;
}
```

The programming language required for developing a screen recorder for Windows PCs is C# with Windows Forms or WPF for the user interface and the Windows API for screen capture functionality. Below is a complete, executable C# code for a basic screen recorder using Windows Forms and the Windows API:

```csharp
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Windows.Forms;

namespace ScreenRecorder
{
    public partial class MainForm : Form
    {
        private bool isRecording = false;
        private string outputPath = "recording.avi";
        private int frameRate = 10;
        private Timer recordingTimer;

        [DllImport("user32.dll")]
        private static extern IntPtr GetDesktopWindow();
        [DllImport("user32.dll")]
        private static extern IntPtr GetWindowDC(IntPtr hWnd);
        [DllImport("user32.dll")]
        private static extern IntPtr ReleaseDC(IntPtr hWnd, IntPtr hDC);
        [DllImport("gdi32.dll")]
        private static extern IntPtr CreateCompatibleBitmap(IntPtr hDC, int nWidth, int nHeight);
        [DllImport("gdi32.dll")]
        private static extern IntPtr CreateCompatibleDC(IntPtr hDC);
        [DllImport("gdi32.dll")]
        private static extern IntPtr SelectObject(IntPtr hDC, IntPtr hObject);
        [DllImport("gdi32.dll")]
        private static extern bool BitBlt(IntPtr hdcDest, int nXDest, int nYDest, int nWidth, int nHeight, IntPtr hdcSrc, int nXSrc, int nYSrc, uint dwRop);
        [DllImport("gdi32.dll")]
        private static extern bool DeleteObject(IntPtr hObject);
        [DllImport("gdi32.dll")]
        private static extern bool DeleteDC(IntPtr hDC);

        public MainForm()
        {
            InitializeComponent();
            recordingTimer = new Timer();
            recordingTimer.Interval = 1000 / frameRate;
            recordingTimer.Tick += RecordingTimer_Tick;
        }

        private void btnRecord_Click(object sender, EventArgs e)
        {
            if (!isRecording)
            {
                isRecording = true;
                btnRecord.Text = "Stop Recording";
                recordingTimer.Start();
            }
            else
            {
                isRecording = false;
                btnRecord.Text = "Start Recording";
                recordingTimer.Stop();
            }
        }

        private void RecordingTimer_Tick(object sender, EventArgs e)
        {
            CaptureScreen();
        }

        private void CaptureScreen()
        {
            IntPtr hDesktop = GetDesktopWindow();
            IntPtr hDesktopDC = GetWindowDC(hDesktop);
            IntPtr hCaptureDC = CreateCompatibleDC(hDesktopDC);
            IntPtr hCaptureBitmap = CreateCompatibleBitmap(hDesktopDC, Screen.PrimaryScreen.Bounds.Width, Screen.PrimaryScreen.Bounds.Height);
            SelectObject(hCaptureDC, hCaptureBitmap);
            BitBlt(hCaptureDC, 0, 0, Screen.PrimaryScreen.Bounds.Width, Screen.PrimaryScreen.Bounds.Height, hDesktopDC, 0, 0, 0x00CC0020);
            using (Bitmap bmp = Image.FromHbitmap(hCaptureBitmap))
            {
                bmp.Save(outputPath, ImageFormat.Jpeg);
            }
            DeleteObject(hCaptureBitmap);
            DeleteDC(hCaptureDC);
            ReleaseDC(hDesktop, hDesktopDC);
        }
    }
}
