```swift
import AVFoundation
import Cocoa

class ScreenRecorder: NSObject {
    private var captureSession: AVCaptureSession!
    private var screenInput: AVCaptureScreenInput!
    private var movieOutput: AVCaptureMovieFileOutput!
    private var outputURL: URL!

    override init() {
        super.init()
        setupCaptureSession()
    }

    private func setupCaptureSession() {
        captureSession = AVCaptureSession()
        captureSession.sessionPreset = .high

        screenInput = AVCaptureScreenInput(displayID: CGMainDisplayID())
        screenInput.minFrameDuration = CMTimeMake(value: 1, timescale: 30)

        if captureSession.canAddInput(screenInput) {
            captureSession.addInput(screenInput)
        }

        movieOutput = AVCaptureMovieFileOutput()
        if captureSession.canAddOutput(movieOutput) {
            captureSession.addOutput(movieOutput)
        }
    }

    func startRecording(to outputURL: URL) {
        self.outputURL = outputURL
        captureSession.startRunning()
        movieOutput.startRecording(to: outputURL, recordingDelegate: self)
    }

    func stopRecording() {
        movieOutput.stopRecording()
        captureSession.stopRunning()
    }
}

extension ScreenRecorder: AVCaptureFileOutputRecordingDelegate {
    func fileOutput(_ output: AVCaptureFileOutput, didFinishRecordingTo outputFileURL: URL, from connections: [AVCaptureConnection], error: Error?) {
        if let error = error {
            print("Recording error: \(error.localizedDescription)")
        } else {
            print("Recording finished successfully at \(outputFileURL.path)")
        }
    }
}

// Example usage:
let recorder = ScreenRecorder()
let documentsURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first!
let outputURL = documentsURL.appendingPathComponent("screenRecording.mov")
recorder.startRecording(to: outputURL)

// To stop recording after some time (e.g., 10 seconds):
DispatchQueue.main.asyncAfter(deadline: .now() + 10) {
    recorder.stopRecording()
}
