```python
import os
import subprocess
import time
import tempfile
from datetime import datetime

class ChromebookScreenRecorder:
    def __init__(self, output_dir="~", fps=30, quality=85):
        self.output_dir = os.path.expanduser(output_dir)
        self.fps = fps
        self.quality = quality
        self.recording_process = None
        self.start_time = None

    def _get_output_path(self):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        return os.path.join(self.output_dir, f"screen_recording_{timestamp}.mp4")

    def start_recording(self):
        output_path = self._get_output_path()
        command = [
            "ffmpeg",
            "-f", "x11grab",
            "-video_size", "1920x1080",
            "-framerate", str(self.fps),
            "-i", ":0.0+0,0",
            "-c:v", "libx264",
            "-crf", str(self.quality),
            "-preset", "ultrafast",
            "-y",
            output_path
        ]

        try:
            self.recording_process = subprocess.Popen(command)
            self.start_time = time.time()
            print(f"Recording started. Output will be saved to: {output_path}")
        except Exception as e:
            print(f"Error starting recording: {e}")

    def stop_recording(self):
        if self.recording_process:
            self.recording_process.terminate()
            self.recording_process.wait()
            duration = time.time() - self.start_time
            print(f"Recording stopped. Duration: {duration:.2f} seconds")
        else:
            print("No recording in progress.")

    def is_recording(self):
        return self.recording_process is not None and self.recording_process.poll() is None

if __name__ == "__main__":
    recorder = ChromebookScreenRecorder()

    print("Chromebook Screen Recorder")
    print("1. Start Recording")
    print("2. Stop Recording")
    print("3. Exit")

    while True:
        choice = input("Enter your choice (1-3): ")

        if choice == "1":
            if recorder.is_recording():
                print("Recording is already in progress.")
            else:
                recorder.start_recording()
        elif choice == "2":
            if recorder.is_recording():
                recorder.stop_recording()
            else:
                print("No recording is currently in progress.")
        elif choice == "3":
            if recorder.is_recording():
                recorder.stop_recording()
            print("Exiting...")
            break
        else:
            print("Invalid choice. Please try again.")
