#!/bin/bash

# Import required libraries
import os
import sqlite3
import re
import hashlib
import base64
from cryptography.fernet import Fernet

# Define the log file path
LOG_FILE = "sqlite_password_scan.log"

# Function to log messages
def log_message(message):
    with open(LOG_FILE, "a") as log_file:
        log_file.write(f"{message}\n")

# Function to check if a string is a possible password field
def is_password_field(field_name):
    password_keywords = ["password", "passwd", "pwd", "secret", "credential", "token"]
    return any(keyword in field_name.lower() for keyword in password_keywords)

# Function to attempt decryption using common methods
def attempt_decryption(encrypted_data):
    decrypted_results = []

    # Try base64 decoding
    try:
        decoded_data = base64.b64decode(encrypted_data).decode('utf-8')
        decrypted_results.append(f"Base64 Decoded: {decoded_data}")
    except:
        pass

    # Try common hashing algorithms (just for identification, not actual decryption)
    hash_algorithms = {
        "MD5": hashlib.md5,
        "SHA1": hashlib.sha1,
        "SHA256": hashlib.sha256
    }

    for algo_name, algo_func in hash_algorithms.items():
        try:
            # Check if the data matches the hash length
            if len(encrypted_data) == algo_func().digest_size * 2:  # Hex representation
                decrypted_results.append(f"Possible {algo_name} Hash: {encrypted_data}")
        except:
            pass

    # Try Fernet decryption (requires a key, which we don't have, so this is just a placeholder)
    try:
        # This is a placeholder since we don't have the actual key
        fernet = Fernet(Fernet.generate_key())
        decrypted_data = fernet.decrypt(encrypted_data.encode()).decode('utf-8')
        decrypted_results.append(f"Fernet Decrypted: {decrypted_data}")
    except:
        pass

    return decrypted_results if decrypted_results else ["No decryption method succeeded"]

# Function to scan an SQLite database for password fields
def scan_database(db_path):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Get all tables in the database
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
        tables = cursor.fetchall()

        password_fields_found = False

        for table in tables:
            table_name = table[0]
            cursor.execute(f"PRAGMA table_info({table_name});")
            columns = cursor.fetchall()

            for column in columns:
                column_name = column[1]
                if is_password_field(column_name):
                    password_fields_found = True
                    log_message(f"Found potential password field: {column_name} in table: {table_name} in database: {db_path}")

                    # Attempt to fetch some sample data (limit to 5 rows for performance)
                    cursor.execute(f"SELECT {column_name} FROM {table_name} LIMIT 5;")
                    sample_data = cursor.fetchall()

                    for data in sample_data:
                        if data[0]:
                            log_message(f"Sample data from {column_name}: {data[0]}")
                            decryption_results = attempt_decryption(str(data[0]))
                            for result in decryption_results:
                                log_message(f"Decryption attempt result: {result}")

        if not password_fields_found:
            log_message(f"No password fields found in database: {db_path}")

        conn.close()
    except Exception as e:
        log_message(f"Error scanning database {db_path}: {str(e)}")

# Main function to find all SQLite files and scan them
def main():
    log_message("Starting SQLite password field scan...")

    # Find all .db, .sqlite, and .sqlite3 files in the system
    for root, dirs, files in os.walk("/"):
        for file in files:
            if file.endswith((".db", ".sqlite", ".sqlite3")):
                db_path = os.path.join(root, file)
                log_message(f"Found SQLite database: {db_path}")
                scan_database(db_path)

    log_message("Scan completed. Results saved to sqlite_password_scan.log")

if __name__ == "__main__":
    main()
```

