import subprocess
import csv
import getpass

def get_keychain_items(username, password):
    try:
        command = [
            'security',
            'dump-keychain',
            '-d',
            f'user={username}',
            f'password={password}',
            'login.keychain'
        ]
        result = subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error accessing keychain: {e.stderr}")
        return None

def parse_keychain_data(keychain_output):
    items = []
    current_item = {}
    in_item = False

    for line in keychain_output.split('\n'):
        line = line.strip()
        if line.startswith('keychain:'):
            in_item = True
            current_item = {"keychain": line.split()[1]}
        elif in_item:
            if line.startswith('class:'):
                current_item["class"] = line.split()[1]
            elif line.startswith('attributes:'):
                current_item["attributes"] = []
            elif line.startswith('0x'):
                if "attributes" in current_item:
                    current_item["attributes"].append(line)
            elif line.startswith('data:'):
                current_item["data"] = line.split(maxsplit=1)[1] if len(line.split()) > 1 else ""
            elif line == "" and current_item:
                items.append(current_item)
                in_item = False
    return items

def write_to_csv(items, output_file):
    if not items:
        print("No items to write to CSV.")
        return

    fieldnames = ["keychain", "class", "attributes", "data"]
    with open(output_file, mode='w', newline='', encoding='utf-8') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for item in items:
            writer.writerow(item)

def main():
    username = input("Enter username: ")
    password = getpass.getpass("Enter password: ")
    output_file = input("Enter output CSV file path: ")

    keychain_output = get_keychain_items(username, password)
    if keychain_output:
        items = parse_keychain_data(keychain_output)
        write_to_csv(items, output_file)
        print(f"Keychain data has been written to {output_file}")

if __name__ == "__main__":
    main()
```

```python
import os
import platform
import sqlite3
import json
import shutil
from pathlib import Path

def get_chrome_config_paths():
    system = platform.system()
    paths = {
        'Windows': [
            os.path.join(os.getenv('LOCALAPPDATA'), 'Google', 'Chrome', 'User Data', 'Default'),
            os.path.join(os.getenv('APPDATA'), 'Google', 'Chrome', 'User Data', 'Default')
        ],
        'Darwin': [
            os.path.join(os.path.expanduser('~'), 'Library', 'Application Support', 'Google', 'Chrome', 'Default')
        ],
        'Linux': [
            os.path.join(os.path.expanduser('~'), '.config', 'google-chrome', 'Default'),
            os.path.join(os.path.expanduser('~'), '.config', 'chromium', 'Default')
        ]
    }
    return paths.get(system, [])

def find_config_files(config_path):
    files = {
        'Login Data': os.path.join(config_path, 'Login Data'),
        'Cookies': os.path.join(config_path, 'Cookies'),
        'Preferences': os.path.join(config_path, 'Preferences'),
        'Web Data': os.path.join(config_path, 'Web Data'),
        'Local State': os.path.join(os.path.dirname(config_path), 'Local State')
    }
    return {name: path for name, path in files.items() if os.path.exists(path)}

def copy_config_files(config_files, output_dir='chrome_config_backup'):
    os.makedirs(output_dir, exist_ok=True)
    backup_paths = {}
    for name, path in config_files.items():
        backup_path = os.path.join(output_dir, name)
        shutil.copy2(path, backup_path)
        backup_paths[name] = backup_path
    return backup_paths

def analyze_preferences(prefs_path):
    with open(prefs_path, 'r', encoding='utf-8') as f:
        prefs = json.load(f)
    return {
        'homepage': prefs.get('homepage', 'Not set'),
        'startup_urls': prefs.get('session', {}).get('restore_on_startup_urls', []),
        'default_search': prefs.get('default_search_provider', {}).get('keyword', 'Not set')
    }

def analyze_login_data(login_data_path):
    try:
        conn = sqlite3.connect(login_data_path)
        cursor = conn.cursor()
        cursor.execute("SELECT origin_url, username_value, password_value FROM logins")
        logins = cursor.fetchall()
        conn.close()
        return [{'url': url, 'username': username, 'password': '*****'} for url, username, _ in logins]
    except sqlite3.Error:
        return []

def analyze_cookies(cookies_path):
    try:
        conn = sqlite3.connect(cookies_path)
        cursor = conn.cursor()
        cursor.execute("SELECT host_key, name, path, expires_utc, is_secure FROM cookies")
        cookies = cursor.fetchall()
        conn.close()
        return [{'host': host, 'name': name, 'path': path, 'expires': expires, 'secure': bool(secure)}
                for host, name, path, expires, secure in cookies]
    except sqlite3.Error:
        return []

def main():
    config_paths = get_chrome_config_paths()
    if not config_paths:
        print("Unsupported operating system or Chrome not installed in standard location.")
        return

    for config_path in config_paths:
        if os.path.exists(config_path):
            print(f"Found Chrome config directory: {config_path}")
            config_files = find_config_files(config_path)
            if config_files:
                print("Found configuration files:")
                for name, path in config_files.items():
                    print(f"- {name}: {path}")

                backup_paths = copy_config_files(config_files)
                print(f"\nBackup created in: {os.path.abspath('chrome_config_backup')}")

                print("\nAnalyzing configuration files...")
                if 'Preferences' in backup_paths:
                    prefs_analysis = analyze_preferences(backup_paths['Preferences'])
                    print("\nPreferences Analysis:")
                    print(json.dumps(prefs_analysis, indent=2))

                if 'Login Data' in backup_paths:
                    logins = analyze_login_data(backup_paths['Login Data'])
                    print("\nLogin Data (passwords masked for security):")
                    print(json.dumps(logins, indent=2))

                if 'Cookies' in backup_paths:
                    cookies = analyze_cookies(backup_paths['Cookies'])
                    print("\nCookies Analysis:")
                    print(json.dumps(cookies[:5], indent=2))  # Show first 5 for brevity
                    if len(cookies) > 5:
                        print(f"... and {len(cookies) - 5} more cookies")

                print("\nAnalysis complete. Backup files are available in the 'chrome_config_backup' directory.")
                return

