import os
import re

def detect_email_config_files(directory):
    patterns = {
        'address': re.compile(r'\baddress\s*=\s*[\'\"]([^\'\"]+)[\'\"]', re.IGNORECASE),
        'port': re.compile(r'\bport\s*=\s*(\d+)', re.IGNORECASE),
        'server': re.compile(r'\bserver\s*=\s*[\'\"]([^\'\"]+)[\'\"]', re.IGNORECASE),
        'password': re.compile(r'\bpassword\s*=\s*[\'\"]([^\'\"]+)[\'\"]', re.IGNORECASE)
    }

    config_files = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                    matches = {}
                    for key, pattern in patterns.items():
                        match = pattern.search(content)
                        if match:
                            matches[key] = match.group(1)
                    if matches:
                        config_files.append((file_path, matches))
            except (UnicodeDecodeError, PermissionError):
                continue

    return config_files

if __name__ == "__main__":
    directory = input("Enter the directory to scan: ")
    config_files = detect_email_config_files(directory)

    if config_files:
        print("Email configuration files found:")
        for file_path, matches in config_files:
            print(f"\nFile: {file_path}")
            for key, value in matches.items():
                print(f"{key}: {value}")
    else:
        print("No email configuration files found.")
