```python
import os
import platform
import winreg
import shutil
import subprocess

def get_system_info():
    info = {}
    info['os'] = platform.system()
    info['os_version'] = platform.version()
    info['architecture'] = platform.architecture()
    info['hostname'] = platform.node()
    info['processor'] = platform.processor()
    return info

def get_registry_keys():
    registry_data = {}
    try:
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion") as key:
            registry_data['CurrentVersion'] = {}
            for i in range(winreg.QueryInfoKey(key)[1]):
                name, value, _ = winreg.EnumValue(key, i)
                registry_data['CurrentVersion'][name] = value
    except Exception as e:
        registry_data['error'] = str(e)
    return registry_data

def get_config_files():
    config_files = {}
    system_root = os.environ.get('SystemRoot', 'C:\\Windows')
    config_files['hosts'] = os.path.join(system_root, 'System32', 'drivers', 'etc', 'hosts')
    config_files['system.ini'] = os.path.join(system_root, 'system.ini')
    config_files['win.ini'] = os.path.join(system_root, 'win.ini')
    return config_files

def copy_config_files(config_files, output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)
    for name, path in config_files.items():
        if os.path.exists(path):
            shutil.copy2(path, os.path.join(output_dir, name))

def main():
    output_dir = 'system_config_backup'
    system_info = get_system_info()
    registry_data = get_registry_keys()
    config_files = get_config_files()

    with open(os.path.join(output_dir, 'system_info.txt'), 'w') as f:
        for key, value in system_info.items():
            f.write(f"{key}: {value}\n")

    with open(os.path.join(output_dir, 'registry_data.txt'), 'w') as f:
        for key, value in registry_data.items():
            f.write(f"{key}: {value}\n")

    copy_config_files(config_files, output_dir)

if __name__ == "__main__":
    main()
