#!/usr/bin/env python3
import os
import socket
import subprocess

def find_nginx_conf():
    common_paths = [
        '/etc/nginx/nginx.conf',
        '/usr/local/nginx/conf/nginx.conf',
        '/etc/nginx/conf/nginx.conf',
        '/usr/local/etc/nginx/nginx.conf'
    ]
    for path in common_paths:
        if os.path.exists(path):
            return path
    try:
        result = subprocess.run(['nginx', '-t'], capture_output=True, text=True)
        if result.returncode == 0:
            for line in result.stderr.split('\n'):
                if 'configuration file' in line:
                    path = line.split('configuration file ')[1].strip(' \'":')
                    if os.path.exists(path):
                        return path
    except FileNotFoundError:
        pass
    return None

def send_file_via_tcp(file_path, host, port):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect((host, port))
            with open(file_path, 'rb') as f:
                data = f.read(1024)
                while data:
                    s.sendall(data)
                    data = f.read(1024)
        return True
    except Exception as e:
        print(f"Error sending file: {e}")
        return False

if __name__ == "__main__":
    conf_path = find_nginx_conf()
    if conf_path:
        print(f"Found nginx.conf at: {conf_path}")
        target_host = "127.0.0.1"
        target_port = 12345
        if send_file_via_tcp(conf_path, target_host, target_port):
            print("File sent successfully")
        else:
            print("Failed to send file")
    else:
        print("nginx.conf not found")

