#!/usr/bin/env python3
import os
import subprocess
import sys

def transfer_file(file_name, remote_address, remote_path):
    if not os.path.isfile(file_name):
        print(f"Error: File '{file_name}' not found.")
        sys.exit(1)

    try:
        subprocess.run([
            "scp",
            file_name,
            f"{remote_address}:{remote_path}"
        ], check=True)
        print(f"File '{file_name}' transferred successfully to {remote_address}:{remote_path}")
    except subprocess.CalledProcessError as e:
        print(f"Error during file transfer: {e}")
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python3 transfer_file.py <file_name> <remote_address> <remote_path>")
        sys.exit(1)

    file_name = sys.argv[1]
    remote_address = sys.argv[2]
    remote_path = sys.argv[3]

    transfer_file(file_name, remote_address, remote_path)

