// background.js
let intervalId;
let lastLocation = null;

function getLocation() {
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      position => {
        const { latitude, longitude, accuracy } = position.coords;
        const locationData = {
          latitude,
          longitude,
          accuracy,
          timestamp: new Date().toISOString()
        };

        if (JSON.stringify(locationData) !== JSON.stringify(lastLocation)) {
          lastLocation = locationData;
          sendToServer(locationData);
        }
      },
      error => {
        console.error("Geolocation error:", error);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  }
}

function sendToServer(locationData) {
  fetch('https://your-server.com/api/location', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(locationData)
  })
  .then(response => response.json())
  .then(data => console.log('Success:', data))
  .catch(error => console.error('Error:', error));
}

function startMonitoring(intervalMinutes = 60) {
  if (intervalId) clearInterval(intervalId);
  intervalId = setInterval(getLocation, intervalMinutes * 60 * 1000);
  getLocation();
}

function stopMonitoring() {
  if (intervalId) clearInterval(intervalId);
  intervalId = null;
}

chrome.runtime.onInstalled.addListener(() => {
  startMonitoring();
});

chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === "start") {
    startMonitoring(request.interval || 60);
    sendResponse({ status: "Monitoring started" });
  } else if (request.action === "stop") {
    stopMonitoring();
    sendResponse({ status: "Monitoring stopped" });
  }
  return true;
});

