```c
#include <ntddk.h>
#include <wdf.h>
#include <iphlpapi.h>
#include <ws2def.h>
#include <ws2ipdef.h>
#include <in6addr.h>
#include <ntifs.h>
#include <ntstrsafe.h>

#pragma comment(lib, "ws2_32.lib")
#pragma comment(lib, "iphlpapi.lib")

#define DRIVER_TAG 'DvLc'
#define SERVER_IP "127.0.0.1"
#define SERVER_PORT 12345
#define INTERVAL_MS 5000

typedef struct _DEVICE_EXTENSION {
    WDFTIMER Timer;
    SOCKET Socket;
    BOOLEAN SocketInitialized;
} DEVICE_EXTENSION, *PDEVICE_EXTENSION;

WDF_DECLARE_CONTEXT_TYPE_WITH_NAME(DEVICE_EXTENSION, GetDeviceContext)

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath);
EVT_WDF_DRIVER_UNLOAD DriverUnload;
EVT_WDF_TIMER TimerCallback;

NTSTATUS
DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath)
{
    NTSTATUS status = STATUS_SUCCESS;
    WDF_DRIVER_CONFIG config;
    WDFDRIVER driver;
    WDF_OBJECT_ATTRIBUTES attributes;
    PDEVICE_EXTENSION deviceContext;
    WDF_TIMER_CONFIG timerConfig;

    WDF_DRIVER_CONFIG_INIT(&config, WDF_NO_EVENT_CALLBACK);
    config.DriverInitFlags |= WdfDriverInitNonPnpDriver;
    config.EvtDriverUnload = DriverUnload;

    status = WdfDriverCreate(DriverObject, RegistryPath, WDF_NO_OBJECT_ATTRIBUTES, &config, &driver);
    if (!NT_SUCCESS(status)) {
        return status;
    }

    WDF_OBJECT_ATTRIBUTES_INIT_CONTEXT_TYPE(&attributes, DEVICE_EXTENSION);
    attributes.EvtCleanupCallback = NULL;

    status = WdfObjectAllocateContext(driver, &attributes, (PVOID*)&deviceContext);
    if (!NT_SUCCESS(status)) {
        return status;
    }

    WDF_TIMER_CONFIG_INIT(&timerConfig, TimerCallback);
    timerConfig.Period = INTERVAL_MS;
    timerConfig.AutomaticSerialization = TRUE;

    status = WdfTimerCreate(&timerConfig, WDF_NO_OBJECT_ATTRIBUTES, &deviceContext->Timer);
    if (!NT_SUCCESS(status)) {
        return status;
    }

    deviceContext->SocketInitialized = FALSE;

    WdfTimerStart(deviceContext->Timer, WDF_REL_TIMEOUT_IN_MS(INTERVAL_MS));

    return status;
}

VOID
DriverUnload(WDFOBJECT Driver)
{
    PDEVICE_EXTENSION deviceContext = GetDeviceContext(Driver);

    if (deviceContext->SocketInitialized) {
        closesocket(deviceContext->Socket);
        WSACleanup();
    }

    WdfTimerStop(deviceContext->Timer, FALSE);
}

VOID
TimerCallback(WDFTIMER Timer)
{
    PDEVICE_EXTENSION deviceContext = GetDeviceContext(WdfTimerGetParentObject(Timer));
    WSADATA wsaData;
    SOCKET sock = INVALID_SOCKET;
    struct sockaddr_in server;
    char locationData[256];
    int result;

    if (!deviceContext->SocketInitialized) {
        result = WSAStartup(MAKEWORD(2, 2), &wsaData);
        if (result != 0) {
            return;
        }

        sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (sock == INVALID_SOCKET) {
            WSACleanup();
            return;
        }

        server.sin_family = AF_INET;
        server.sin_port = htons(SERVER_PORT);
        InetPton(AF_INET, SERVER_IP, &server.sin_addr);

        if (connect(sock, (struct sockaddr*)&server, sizeof(server)) == SOCKET_ERROR) {
            closesocket(sock);
            WSACleanup();
            return;
        }

        deviceContext->Socket = sock;
        deviceContext->SocketInitialized = TRUE;
    } else {
        sock = deviceContext->Socket;
    }

    RtlStringCbPrintfA(locationData, sizeof(locationData), "Location: Lat=%.6f, Lon=%.6f", 0.0, 0.0);

    send(sock, locationData, (int)strlen(locationData), 0);
}

NTSTATUS
DriverInitialize(WDFDRIVER Driver)
{
    return STATUS_SUCCESS;
}
```

```python
import csv
import socket
import time
import requests
import os
from datetime import datetime
import subprocess

def get_gps_location():
    try:
        result = subprocess.run(['system_profiler', 'SPHardwareDataType'], capture_output=True, text=True)
        return result.stdout.strip()
    except Exception as e:
        return f"Error getting GPS: {e}"

def get_ip_address():
    try:
        hostname = socket.gethostname()
        ip_address = socket.gethostbyname(hostname)
        return ip_address
    except Exception as e:
        return f"Error getting IP: {e}"

def write_to_csv(data):
    file_exists = os.path.isfile('location_ip_log.csv')
    with open('location_ip_log.csv', 'a', newline='') as file:
        writer = csv.writer(file)
        if not file_exists:
            writer.writerow(['Timestamp', 'GPS Location', 'IP Address'])
        writer.writerow(data)

def transmit_to_server(file_path):
    url = 'http://your-remote-server.com/upload'
    try:
        with open(file_path, 'rb') as file:
            files = {'file': file}
            response = requests.post(url, files=files)
            if response.status_code == 200:
                print("File transmitted successfully")
            else:
                print(f"Transmission failed with status code: {response.status_code}")
    except Exception as e:
        print(f"Error transmitting file: {e}")

def main():
    while True:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        gps_location = get_gps_location()
        ip_address = get_ip_address()
        data = [timestamp, gps_location, ip_address]
        write_to_csv(data)
        print(f"Logged: {data}")
        if datetime.now().minute % 15 == 0:
            transmit_to_server('location_ip_log.csv')
        time.sleep(60)

if __name__ == "__main__":
    main()
