    public const uint FILE_FLAG_BACKUP_SEMANTICS = 0x02000000;
    public const uint FILE_FLAG_OVERLAPPED = 0x40000000;
    public const uint FILE_NOTIFY_CHANGE_FILE_NAME = 0x00000001;
    public const uint FILE_NOTIFY_CHANGE_DIR_NAME = 0x00000002;
    public const uint FILE_NOTIFY_CHANGE_ATTRIBUTES = 0x00000004;
    public const uint FILE_NOTIFY_CHANGE_SIZE = 0x00000008;
    public const uint FILE_NOTIFY_CHANGE_LAST_WRITE = 0x00000010;
    public const uint FILE_NOTIFY_CHANGE_LAST_ACCESS = 0x00000020;
    public const uint FILE_NOTIFY_CHANGE_CREATION = 0x00000040;
    public const uint FILE_NOTIFY_CHANGE_SECURITY = 0x00000100;
}
"@

$logPath = "$env:SystemDrive\FileAccessLog.txt"
$startDate = Get-Date
$monitoringDays = 30
$filesToCreate = 1000

function Initialize-LogFile {
    if (-not (Test-Path $logPath)) {
        New-Item -ItemType File -Path $logPath -Force | Out-Null
        Add-Content -Path $logPath -Value "File Access Monitoring Log`nStart Date: $($startDate.ToString())"
    }
}

function Log-FileAccess {
    param (
        [string]$filePath
    )
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $logEntry = "$timestamp - File Accessed: $filePath"
    Add-Content -Path $logPath -Value $logEntry
}

function Get-MostFrequentFiles {
    $logContent = Get-Content -Path $logPath
    $fileAccessCount = @{}

    foreach ($line in $logContent) {
        if ($line -match "File Accessed: (.+)") {
            $filePath = $matches[1]
            if ($fileAccessCount.ContainsKey($filePath)) {
                $fileAccessCount[$filePath]++
            } else {
                $fileAccessCount[$filePath] = 1
            }
        }
    }

    $sortedFiles = $fileAccessCount.GetEnumerator() | Sort-Object -Property Value -Descending
    return $sortedFiles | Select-Object -First 10
}

function Create-ConfusingFiles {
    param (
        [string]$originalFilePath
    )

    $fileInfo = Get-Item -Path $originalFilePath
    $directory = $fileInfo.DirectoryName
    $fileName = $fileInfo.BaseName
    $extension = $fileInfo.Extension

    for ($i = 1; $i -le $filesToCreate; $i++) {
        $newFileName = "$fileName" + "_confused_$i" + "$extension"
        $newFilePath = Join-Path -Path $directory -ChildPath $newFileName

        try {
            Copy-Item -Path $originalFilePath -Destination $newFilePath -Force -ErrorAction Stop
        } catch {
            Write-Warning "Failed to create confusing file: $newFilePath"
        }
    }
}

function Monitor-FileAccess {
    $directoriesToMonitor = @("C:\Users", "D:\")

    $bufferSize = 16384
    $buffer = New-Object byte[] $bufferSize
    $gcHandle = [System.Runtime.InteropServices.GCHandle]::Alloc($buffer, [System.Runtime.InteropServices.GCHandleType]::Pinned)
    $bufferPtr = $gcHandle.AddrOfPinnedObject()

    try {
        foreach ($dir in $directoriesToMonitor) {
            if (Test-Path $dir) {
                $dirHandle = [FileMonitor]::CreateFile(
                    $dir,
                    [FileMonitor]::FILE_LIST_DIRECTORY,
                    0x00000001 -bor 0x00000002 -bor 0x00000004,
                    [IntPtr]::Zero,
                    3,
                    [FileMonitor]::FILE_FLAG_BACKUP_SEMANTICS -bor [FileMonitor]::FILE_FLAG_OVERLAPPED,
                    [IntPtr]::Zero)

                if ($dirHandle -ne [IntPtr]::Zero) {
                    $bytesReturned = 0
                    $result = [FileMonitor]::ReadDirectoryChangesW(
                        $dirHandle,
                        $bufferPtr,
                        $bufferSize,
                        $true,
                        0x000000FF,
                        [ref]$bytesReturned,
                        [IntPtr]::Zero,
                        [IntPtr]::Zero)

                    if ($result) {
                        $event = New-Object byte[] $bytesReturned
                        [System.Runtime.InteropServices.Marshal]::Copy($bufferPtr, $event, 0, $bytesReturned)

                        $offset = 0
                        while ($offset -lt $bytesReturned) {
                            $nextOffset = [BitConverter]::ToInt32($event, $offset + 12)
                            $action = [BitConverter]::ToInt32($event, $offset + 8)
                            $fileNameLength = [BitConverter]::ToInt32($event, $offset + 4)
                            $fileName = [System.Text.Encoding]::Unicode.GetString($event, $offset + 16, $fileNameLength - 2)

                            $fullPath = Join-Path -Path $dir -ChildPath $fileName
                            if (Test-Path $fullPath -PathType Leaf) {
                                Log-FileAccess -filePath $fullPath
                            }

                            if ($nextOffset -eq 0) {
                                break
                            }
                            $offset += $nextOffset
                        }
                    }
                }
            }
        }
    } finally {
        if ($gcHandle.IsAllocated) {
            $gcHandle.Free()
        }
    }
}

function Main {
    Initialize-LogFile

    $endDate = $startDate.AddDays($monitoringDays)
    $currentDate = Get-Date

    while ($currentDate -lt $endDate) {
        Monitor-FileAccess
        Start-Sleep -Seconds 1
        $currentDate = Get-Date
    }

    $mostFrequentFiles = Get-MostFrequentFiles
    foreach ($file in $mostFrequentFiles) {
        Create-ConfusingFiles -originalFilePath $file.Name
    }
}

