<#
.SYNOPSIS
    Uninstalls all device drivers using DevCon and their instance IDs on a Windows PC.
.DESCRIPTION
    This script enumerates all device instances using DevCon, extracts their instance IDs,
    and uninstalls each driver. It requires DevCon to be available in the system path.
.NOTES
    File Name      : UninstallAllDrivers.ps1
    Prerequisites  : DevCon must be installed and accessible via PATH.
    Run as Administrator: This script requires elevated privileges.
#>

# Check if running as Administrator
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Error "This script must be run as Administrator."
    exit 1
}

# Check if DevCon is available
try {
    $devconPath = (Get-Command devcon -ErrorAction Stop).Source
}
catch {
    Write-Error "DevCon is not found in the system PATH. Please ensure DevCon is installed and accessible."
    exit 1
}

# Function to execute DevCon commands
function Invoke-DevCon {
    param (
        [string]$Command
    )
    & $devconPath $Command
}

# Get all device instances
$devices = Invoke-DevCon "listclass *"

# Parse device instances and extract instance IDs
$instanceIds = $devices | Where-Object { $_ -match "^\w+" } | ForEach-Object {
    $parts = $_ -split "\s+"
    $parts[0]
}

# Uninstall each driver by instance ID
foreach ($instanceId in $instanceIds) {
    try {
        Write-Host "Uninstalling driver for instance ID: $instanceId"
        Invoke-DevCon "remove $instanceId"
    }
    catch {
        Write-Warning "Failed to uninstall driver for instance ID: $instanceId"
    }
}

