$videoExtensions = @('*.mp4', '*.mov', '*.avi', '*.mkv', '*.flv', '*.wmv', '*.webm', '*.m4v', '*.mpg', '*.mpeg', '*.3gp', '*.3g2', '*.mts', '*.m2ts', '*.ts', '*.ogv')

