#Requires -RunAsAdministrator

$ErrorActionPreference = "Stop"

function Set-ServiceStartupMode {
    param (
        [string]$ServiceName,
        [string]$StartupMode
    )

    $service = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
    if (-not $service) {
        Write-Error "Service $ServiceName not found."
        return
    }

    $currentStartup = (Get-WmiObject -Class Win32_Service -Filter "Name='$ServiceName'").StartMode
    if ($currentStartup -eq $StartupMode) {
        Write-Host "Service $ServiceName is already set to $StartupMode."
        return
    }

    try {
        Set-Service -Name $ServiceName -StartupType $StartupMode
        Write-Host "Successfully set $ServiceName startup mode to $StartupMode."
    }
    catch {
        Write-Error "Failed to set startup mode for $ServiceName : $_"
    }
}

function Modify-SpoolerService {
    param (
        [string]$Action
    )

    $spoolerService = "Spooler"
    $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$spoolerService"
    $backupPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Spooler_Backup_$(Get-Date -Format 'yyyyMMddHHmmss')"

    try {
        if (-not (Test-Path $regPath)) {
            Write-Error "Spooler service registry path not found."
            return
        }

        if ($Action -eq "Backup") {
            Copy-Item -Path $regPath -Destination $backupPath -Recurse -Force
            Write-Host "Backup of Spooler registry settings created at $backupPath"
        }
        elseif ($Action -eq "Disable") {
            Set-ServiceStartupMode -ServiceName $spoolerService -StartupMode "Disabled"
            Stop-Service -Name $spoolerService -Force -ErrorAction SilentlyContinue
        }
        elseif ($Action -eq "Enable") {
            Set-ServiceStartupMode -ServiceName $spoolerService -StartupMode "Automatic"
            Start-Service -Name $spoolerService -ErrorAction SilentlyContinue
        }
        elseif ($Action -eq "Optimize") {
            Set-ItemProperty -Path $regPath -Name "DependOnService" -Value "RPCSS" -Force
            Set-ItemProperty -Path "$regPath\Parameters" -Name "EventLog" -Value "0" -Force
            Write-Host "Optimized Spooler service configuration."
        }
        else {
            Write-Error "Invalid action specified for Spooler service."
        }
    }
    catch {
        Write-Error "Error modifying Spooler service: $_"
    }
}

function Disable-NonCriticalServices {
    $nonCriticalServices = @(
        "DiagTrack",
        "dmwappushservice",
        "WSearch",
        "wuauserv"
    )

    foreach ($service in $nonCriticalServices) {
        try {
            Set-ServiceStartupMode -ServiceName $service -StartupMode "Disabled"
            Stop-Service -Name $service -Force -ErrorAction SilentlyContinue
        }
        catch {
            Write-Warning "Could not disable $service : $_"
        }
    }
}

function Restore-SpoolerBackup {
    param (
        [string]$BackupPath
    )

    if (-not (Test-Path $BackupPath)) {
        Write-Error "Backup path not found: $BackupPath"
        return
    }

    try {
        Remove-Item -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Spooler" -Recurse -Force
        Copy-Item -Path $BackupPath -Destination "HKLM:\SYSTEM\CurrentControlSet\Services\Spooler" -Recurse -Force
        Write-Host "Spooler registry settings restored from backup."
    }
    catch {
        Write-Error "Error restoring Spooler backup: $_"
    }
}

function Show-Menu {
    Write-Host "`nWindows Service Configuration Script`n"
    Write-Host "1. Disable Spooler Service"
    Write-Host "2. Enable Spooler Service"
    Write-Host "3. Optimize Spooler Service"
    Write-Host "4. Backup Spooler Configuration"
    Write-Host "5. Restore Spooler Configuration"
    Write-Host "6. Disable Non-Critical Services"
    Write-Host "7. Exit`n"
}

function Main {
    while ($true) {
        Show-Menu
        $choice = Read-Host "Enter your choice (1-7)"

        switch ($choice) {
            "1" { Modify-SpoolerService -Action "Disable" }
            "2" { Modify-SpoolerService -Action "Enable" }
            "3" { Modify-SpoolerService -Action "Optimize" }
            "4" { Modify-SpoolerService -Action "Backup" }
            "5" {
                $backupPath = Read-Host "Enter the backup path (e.g., HKLM:\SYSTEM\CurrentControlSet\Services\Spooler_Backup_*)"
                Restore-SpoolerBackup -BackupPath $backupPath
            }
            "6" { Disable-NonCriticalServices }
            "7" { exit }
            default { Write-Host "Invalid choice. Please try again." }
        }

        Write-Host "`nPress any key to continue..."
        $null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
    }
}

