#!/usr/bin/env python3
import os
import shutil
import sys

def backup_resolv_conf():
    shutil.copy('/etc/resolv.conf', '/etc/resolv.conf.bak')

def modify_resolv_conf(dns_servers, domain=None, search_domains=None):
    lines = []
    if domain:
        lines.append(f"domain {domain}")
    if search_domains:
        for search_domain in search_domains:
            lines.append(f"search {search_domain}")
    for dns_server in dns_servers:
        lines.append(f"nameserver {dns_server}")
    with open('/etc/resolv.conf', 'w') as f:
        f.write('\n'.join(lines))

def restore_resolv_conf():
    shutil.copy('/etc/resolv.conf.bak', '/etc/resolv.conf')

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 script.py <dns_server1> [<dns_server2> ...] [--domain <domain>] [--search <search_domain1> [<search_domain2> ...]]")
        sys.exit(1)

    dns_servers = []
    domain = None
    search_domains = []

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == '--domain':
            i += 1
            if i < len(sys.argv):
                domain = sys.argv[i]
        elif arg == '--search':
            i += 1
            while i < len(sys.argv) and not sys.argv[i].startswith('--'):
                search_domains.append(sys.argv[i])
                i += 1
            continue
        else:
            dns_servers.append(arg)
        i += 1

    if not dns_servers:
        print("Error: At least one DNS server must be provided.")
        sys.exit(1)

    backup_resolv_conf()
    try:
        modify_resolv_conf(dns_servers, domain, search_domains)
        print("DNS configuration updated successfully.")
    except Exception as e:
        print(f"Error: {e}")
        restore_resolv_conf()
        print("Restored original DNS configuration.")

if __name__ == "__main__":
    main()

