#!/usr/bin/env python3
import subprocess
import os
import plistlib
import shutil
from pathlib import Path

def backup_plist(file_path):
    backup_path = f"{file_path}.backup"
    shutil.copy2(file_path, backup_path)
    return backup_path

def modify_plist(file_path, modifications):
    try:
        with open(file_path, 'rb') as f:
            plist_data = plistlib.load(f)

        for key, value in modifications.items():
            plist_data[key] = value

        with open(file_path, 'wb') as f:
            plistlib.dump(plist_data, f)

        print(f"Successfully modified {file_path}")
    except Exception as e:
        print(f"Error modifying {file_path}: {e}")

def main():
    plist_files = {
        "/Library/Preferences/.GlobalPreferences.plist": {
            "AppleInterfaceStyle": "Dark",
            "AppleShowAllExtensions": True
        },
        "~/Library/Preferences/com.apple.dock.plist": {
            "autohide": True,
            "tilesize": 36
        }
    }

    for file_path, modifications in plist_files.items():
        expanded_path = os.path.expanduser(file_path)
        if os.path.exists(expanded_path):
            print(f"Backing up {expanded_path}")
            backup_plist(expanded_path)
            modify_plist(expanded_path, modifications)
        else:
            print(f"File not found: {expanded_path}")

if __name__ == "__main__":
    main()
