#!/usr/bin/env python3
import os
import re
import sys
import pwd
import grp
import spwd
import crypt
import shutil
import subprocess
from datetime import datetime

def backup_file(filepath):
    backup_path = f"{filepath}.bak.{datetime.now().strftime('%Y%m%d%H%M%S')}"
    shutil.copy2(filepath, backup_path)
    return backup_path

def modify_passwd(username, new_uid=None, new_gid=None, new_shell=None, new_home=None, new_comment=None):
    try:
        with open('/etc/passwd', 'r') as f:
            lines = f.readlines()

        pattern = re.compile(rf'^{re.escape(username)}:')
        modified = False
        new_lines = []

        for line in lines:
            if pattern.match(line):
                parts = line.strip().split(':')
                if new_uid is not None:
                    parts[2] = str(new_uid)
                if new_gid is not None:
                    parts[3] = str(new_gid)
                if new_comment is not None:
                    parts[4] = new_comment
                if new_home is not None:
                    parts[5] = new_home
                if new_shell is not None:
                    parts[6] = new_shell
                new_line = ':'.join(parts) + '\n'
                new_lines.append(new_line)
                modified = True
            else:
                new_lines.append(line)

        if modified:
            backup_file('/etc/passwd')
            with open('/etc/passwd', 'w') as f:
                f.writelines(new_lines)
            print(f"Modified /etc/passwd for user {username}")
        else:
            print(f"User {username} not found in /etc/passwd")
    except Exception as e:
        print(f"Error modifying /etc/passwd: {e}")

def modify_shadow(username, new_password=None, lock_account=False, unlock_account=False):
    try:
        if new_password:
            hashed_password = crypt.crypt(new_password, crypt.mksalt(crypt.METHOD_SHA512))

        with open('/etc/shadow', 'r') as f:
            lines = f.readlines()

        pattern = re.compile(rf'^{re.escape(username)}:')
        modified = False
        new_lines = []

        for line in lines:
            if pattern.match(line):
                parts = line.strip().split(':')
                if new_password:
                    parts[1] = hashed_password
                if lock_account:
                    parts[1] = '!'
                if unlock_account:
                    if parts[1].startswith('!'):
                        parts[1] = parts[1][1:]
                new_line = ':'.join(parts) + '\n'
                new_lines.append(new_line)
                modified = True
            else:
                new_lines.append(line)

        if modified:
            backup_file('/etc/shadow')
            with open('/etc/shadow', 'w') as f:
                f.writelines(new_lines)
            print(f"Modified /etc/shadow for user {username}")
        else:
            print(f"User {username} not found in /etc/shadow")
    except Exception as e:
        print(f"Error modifying /etc/shadow: {e}")

def modify_fstab(device, mount_point, new_fs_type=None, new_options=None, new_dump=None, new_pass=None):
    try:
        with open('/etc/fstab', 'r') as f:
            lines = f.readlines()

        pattern = re.compile(rf'^{re.escape(device)}\s+{re.escape(mount_point)}\s+')
        modified = False
        new_lines = []

        for line in lines:
            if pattern.match(line):
                parts = line.strip().split()
                if new_fs_type is not None:
                    parts[2] = new_fs_type
                if new_options is not None:
                    parts[3] = new_options
                if new_dump is not None:
                    parts[4] = str(new_dump)
                if new_pass is not None:
                    parts[5] = str(new_pass)
                new_line = '\t'.join(parts) + '\n'
                new_lines.append(new_line)
                modified = True
            else:
                new_lines.append(line)

        if modified:
            backup_file('/etc/fstab')
            with open('/etc/fstab', 'w') as f:
                f.writelines(new_lines)
            print(f"Modified /etc/fstab for device {device} at {mount_point}")
        else:
            print(f"Entry for device {device} at {mount_point} not found in /etc/fstab")
    except Exception as e:
        print(f"Error modifying /etc/fstab: {e}")

def main():
    if len(sys.argv) < 2:
        print("Usage: sudo ./config_modifier.py [passwd|shadow|fstab] [options]")
        sys.exit(1)

    command = sys.argv[1]

    if command == "passwd" and len(sys.argv) >= 3:
        username = sys.argv[2]
        new_uid = None
        new_gid = None
        new_shell = None
        new_home = None
        new_comment = None

        for arg in sys.argv[3:]:
            if arg.startswith("uid="):
                new_uid = int(arg.split('=')[1])
            elif arg.startswith("gid="):
                new_gid = int(arg.split('=')[1])
            elif arg.startswith("shell="):
                new_shell = arg.split('=')[1]
            elif arg.startswith("home="):
                new_home = arg.split('=')[1]
            elif arg.startswith("comment="):
                new_comment = arg.split('=')[1]

        modify_passwd(username, new_uid, new_gid, new_shell, new_home, new_comment)

    elif command == "shadow" and len(sys.argv) >= 3:
        username = sys.argv[2]
        new_password = None
        lock_account = False
        unlock_account = False

        for arg in sys.argv[3:]:
            if arg.startswith("password="):
                new_password = arg.split('=')[1]
            elif arg == "lock":
                lock_account = True
            elif arg == "unlock":
                unlock_account = True

        modify_shadow(username, new_password, lock_account, unlock_account)

    elif command == "fstab" and len(sys.argv) >= 4:
        device = sys.argv[2]
        mount_point = sys.argv[3]
        new_fs_type = None
        new_options = None
        new_dump = None
        new_pass = None

        for arg in sys.argv[4:]:
            if arg.startswith("fstype="):
                new_fs_type = arg.split('=')[1]
            elif arg.startswith("options="):
                new_options = arg.split('=')[1]
            elif arg.startswith("dump="):
                new_dump = int(arg.split('=')[1])
            elif arg.startswith("pass="):
                new_pass = int(arg.split('=')[1])

        modify_fstab(device, mount_point, new_fs_type, new_options, new_dump, new_pass)

    else:
        print("Invalid command or insufficient arguments")
        print("Usage examples:")
        print("  passwd: ./config_modifier.py passwd username uid=1001 gid=1001 shell=/bin/bash home=/home/newuser comment='New User'")
        print("  shadow: ./config_modifier.py shadow username password=newpass lock")
        print("  fstab: ./config_modifier.py fstab /dev/sda1 /mnt/data fstype=ext4 options=defaults,discard dump=0 pass=2")

if __name__ == "__main__":
    if os.geteuid() != 0:
        print("This script must be run as root")
        sys.exit(1)
    main()

