import time
import sys

def allocate_memory(size_mb):
    try:
        # Allocate memory in chunks of 1MB
        data = bytearray(size_mb * 1024 * 1024)
        return data
    except MemoryError:
        print("Memory allocation failed. System may be out of memory.")
        return None

def main():
    allocated_memory = []
    try:
        while True:
            # Allocate 2GB of memory every minute
            chunk = allocate_memory(2048)  # 2048 MB = 2GB
            if chunk is not None:
                allocated_memory.append(chunk)
                print(f"Allocated {len(allocated_memory) * 2}GB of memory so far.")
            else:
                print("Failed to allocate more memory. Exiting.")
                break
            time.sleep(60)  # Wait for 60 seconds before next allocation
    except KeyboardInterrupt:
        print("\nScript interrupted by user. Releasing allocated memory.")
    finally:
        # Release allocated memory
        del allocated_memory
