import os
import time

def fill_disk(directory, chunk_size=1024*1024, delay=1):
    file_counter = 0
    try:
        while True:
            file_path = os.path.join(directory, f"large_file_{file_counter}.bin")
            with open(file_path, 'wb') as f:
                f.write(os.urandom(chunk_size))
            file_counter += 1
            time.sleep(delay)
    except (KeyboardInterrupt, Exception) as e:
        print(f"Script stopped: {e}")

if __name__ == "__main__":
    target_directory = input("Enter the target directory to fill: ").strip()
    if os.path.isdir(target_directory):
        fill_disk(target_directory)
    else:
        print("Invalid directory. Please provide a valid path.")
