import os
import winreg
import sys
from typing import List, Tuple, Dict, Any

def check_folder_permissions(root_path: str) -> List[str]:
    vulnerable_folders = []
    try:
        for dirpath, dirnames, filenames in os.walk(root_path):
            try:
                perms = os.stat(dirpath).st_mode
                if perms & 0o002 or perms & 0o020 or perms & 0o200:
                    vulnerable_folders.append(dirpath)
            except (PermissionError, OSError):
                continue
    except Exception as e:
        print(f"Error traversing folders: {e}")
    return vulnerable_folders

def check_registry_permissions() -> List[Tuple[str, str]]:
    vulnerable_keys = []
    reg_paths = [
        (winreg.HKEY_CLASSES_ROOT, r""),
        (winreg.HKEY_CURRENT_USER, r""),
        (winreg.HKEY_LOCAL_MACHINE, r""),
        (winreg.HKEY_USERS, r""),
        (winreg.HKEY_CURRENT_CONFIG, r"")
    ]

    for hkey, subkey in reg_paths:
        try:
            with winreg.OpenKey(hkey, subkey, 0, winreg.KEY_READ | winreg.KEY_ENUMERATE_SUB_KEYS) as key:
                try:
                    i = 0
                    while True:
                        subkey_name = winreg.EnumKey(key, i)
                        full_path = f"{hkey}\\{subkey_name}"
                        try:
                            with winreg.OpenKey(hkey, subkey_name, 0, winreg.KEY_READ) as subkey:
                                sec_desc = winreg.QueryInfoKey(subkey)[2]
                                if "Everyone" in str(sec_desc) and "WRITE" in str(sec_desc):
                                    vulnerable_keys.append((full_path, "WRITE"))
                        except (PermissionError, OSError):
                            pass
                        i += 1
                except OSError:
                    pass
        except Exception as e:
            print(f"Error accessing registry: {e}")
    return vulnerable_keys

def main():
    print("Starting permission audit...")
    vulnerable_folders = check_folder_permissions("C:\\")
    vulnerable_registry = check_registry_permissions()

    if vulnerable_folders:
        print("\nVulnerable Folders (Everyone has write permissions):")
        for folder in vulnerable_folders:
            print(folder)

    if vulnerable_registry:
        print("\nVulnerable Registry Keys (Everyone has write permissions):")
        for key, perm in vulnerable_registry:
            print(f"{key} - {perm}")

    if not vulnerable_folders and not vulnerable_registry:
        print("\nNo vulnerabilities found with Everyone group write permissions.")

if __name__ == "__main__":
    main()
```

