#!/usr/bin/env python3
import os
import sys
import pwd
import logging

logging.basicConfig(filename='privilege_escalation.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def check_permissions(file_path):
    try:
        stat_info = os.stat(file_path)
        permissions = oct(stat_info.st_mode)[-3:]
        owner = pwd.getpwuid(stat_info.st_uid).pw_name
        group = pwd.getpwuid(stat_info.st_gid).pw_name
        logging.info(f"File: {file_path}, Permissions: {permissions}, Owner: {owner}, Group: {group}")
        return permissions, owner, group
    except Exception as e:
        logging.error(f"Error checking permissions: {e}")
        return None, None, None

def read_file(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            logging.info(f"Successfully read file: {file_path}")
            return content
    except Exception as e:
        logging.error(f"Error reading file: {e}")
        return None

def escalate_privileges():
    try:
        if os.geteuid() != 0:
            logging.info("Attempting to escalate privileges...")
            os.execlp('sudo', 'sudo', 'python3', sys.argv[0])
        else:
            logging.info("Already running with root privileges")
    except Exception as e:
        logging.error(f"Privilege escalation failed: {e}")

def main():
    file_path = '/etc/passwd'
    permissions, owner, group = check_permissions(file_path)
    if permissions:
        print(f"Permissions for {file_path}: {permissions}")
        print(f"Owner: {owner}, Group: {group}")
    content = read_file(file_path)
    if content:
        print("File content read successfully")
    escalate_privileges()

if __name__ == "__main__":
    main()

