#!/usr/bin/env python3
import os
import stat
import sys
import subprocess

CRON_FILE = "/etc/crontab"

def check_permissions():
    try:
        file_stat = os.stat(CRON_FILE)
        permissions = stat.filemode(file_stat.st_mode)
        uid = file_stat.st_uid
        gid = file_stat.st_gid
        print(f"Current permissions: {permissions}")
        print(f"Owner: {uid}, Group: {gid}")
        return file_stat
    except FileNotFoundError:
        print(f"Error: {CRON_FILE} not found.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied when accessing {CRON_FILE}.")
        sys.exit(1)

def attempt_modification():
    try:
        with open(CRON_FILE, "a") as f:
            f.write("\n# Test job added by script\n* * * * * root echo 'Test cron job executed' >> /var/log/cron_test.log 2>&1\n")
        print("Successfully modified the cron file.")
    except PermissionError:
        print("Error: Permission denied when attempting to modify the cron file.")
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

def main():
    print(f"Checking permissions for {CRON_FILE}...")
    file_stat = check_permissions()

    if file_stat.st_uid != 0:
        print("Warning: Cron file is not owned by root. This is a security risk.")
    if file_stat.st_mode & stat.S_IWGRP or file_stat.st_mode & stat.S_IWOTH:
        print("Warning: Cron file is writable by group or others. This is a security risk.")

    print("\nAttempting to modify the cron file...")
    attempt_modification()

if __name__ == "__main__":
    main()

