import multiprocessing
import time
import math

def calculate_factorial(n):
    return math.factorial(n)

def calculate_square_root(n):
    return math.sqrt(n)

def calculate_power(base, exponent):
    return math.pow(base, exponent)

def worker(task):
    if task['type'] == 'factorial':
        return calculate_factorial(task['value'])
    elif task['type'] == 'square_root':
        return calculate_square_root(task['value'])
    elif task['type'] == 'power':
        return calculate_power(task['base'], task['exponent'])

def main():
    tasks = [
        {'type': 'factorial', 'value': 100},
        {'type': 'square_root', 'value': 16},
        {'type': 'power', 'base': 2, 'exponent': 10},
        {'type': 'factorial', 'value': 200},
        {'type': 'square_root', 'value': 25},
        {'type': 'power', 'base': 3, 'exponent': 5},
        {'type': 'factorial', 'value': 150},
        {'type': 'square_root', 'value': 36},
        {'type': 'power', 'base': 4, 'exponent': 4},
        {'type': 'factorial', 'value': 250},
        {'type': 'square_root', 'value': 49},
        {'type': 'power', 'base': 5, 'exponent': 3}
    ]

    start_time = time.time()
    with multiprocessing.Pool(processes=multiprocessing.cpu_count()) as pool:
        results = pool.map(worker, tasks)
    end_time = time.time()

    print(f"Results: {results}")
    print(f"Time taken: {end_time - start_time:.2f} seconds")

if __name__ == "__main__":
    main()
