#include <stdio.h>
#include <cuda_runtime.h>

__global__ void computeTask(float *input, float *output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = input[idx] * input[idx]; // Example computation: square each element
    }
}

int main() {
    const int size = 1 << 20; // 1M elements
    float *h_input, *h_output;
    float *d_input, *d_output;

    // Allocate host memory
    h_input = (float*)malloc(size * sizeof(float));
    h_output = (float*)malloc(size * sizeof(float));

    // Initialize input data
    for (int i = 0; i < size; i++) {
        h_input[i] = i % 100; // Example data
    }

    // Allocate device memory
    cudaMalloc(&d_input, size * sizeof(float));
    cudaMalloc(&d_output, size * sizeof(float));

    // Copy data to device
    cudaMemcpy(d_input, h_input, size * sizeof(float), cudaMemcpyHostToDevice);

    // Configure and launch kernel
    int blockSize = 256;
    int numBlocks = (size + blockSize - 1) / blockSize;
    computeTask<<<numBlocks, blockSize>>>(d_input, d_output, size);

    // Copy results back to host
